// 简体中文 stories: I18N["zh-CN"].stories["<civ id>:<activity>"] = "…" (same keys as cultures/stories/asia.js).
Object.assign(I18N["zh-CN"].stories, {
  // ── Chinese ──
  "chinese:hunt": "从1681年起，每到秋天，康熙帝便北出长城，前往木兰围场行猎。数以千计的八旗兵在林中围成巨大的圆圈，再慢慢收紧，把鹿、野猪和老虎赶到皇帝的箭下。这是游乐，也是操练：满洲朝廷担心太平日子和城市生活会让骑手们变得软弱。康熙对自己猎到的老虎数目颇为自豪，围猎结束时还要设宴款待前来观猎的蒙古王公。",
  "chinese:battle": "1561年，浙江沿海在倭寇的劫掠下烽火连天。将军戚继光从义乌招募矿工和农民，操练他们使用鸳鸯阵：十二人如一人般行动，藤牌在前，长长的毛竹枪保留枝杈，用来缠住敌人的刀。他们在台州九战九捷。对海边的村庄来说，这仿佛是多年来第一次可以望着大海而不再心惊胆战。",
  "chinese:ritual": "每逢冬至，明清两代的皇帝都要离开紫禁城，前往永乐年间于1420年建成的天坛。天亮之前，在寒气之中，天子登上圜丘坛三层汉白玉台阶，向上天献上玉、帛、燔烧的牛犊和音乐。乐师们奏着缓慢而古老的雅乐。人们觉得，来年整个天下的收成与太平，都系于这一个人在黑暗中是否行礼得当。",
  "chinese:rain": "1876年至1879年，华北大地久旱无雨，这就是丁戊奇荒，死者或达九百万至一千三百万人。地方官率众列队前往龙王庙，把龙王像抬到烈日下晒，好让他亲身尝尝干旱的滋味，人们手里还拿着柳枝。农民们每天清晨望着龟裂的田地和空荡荡的天空。等雨终于回来，幸存的人们又默默地播下种子，因为日子总得这样过下去。",
  "chinese:wind": "1405年至1433年间，郑和率领七次庞大的宝船船队横渡印度洋。他在刘家港和长乐立下石碑，感谢天妃，也就是海神妈祖，在风暴中救了他们：每当狂风怒号、巨浪如山，水手们向她呼救，桅顶便出现神光，海面随之平静。这些碑文读来不像夸耀，倒更像一群本以为必死无疑的人如释重负的祷告。",
  "chinese-early:fire": "公元前206年，秦朝灭亡之后，起兵反秦的项羽进入咸阳，焚烧了始皇帝的宫殿。司马迁记载，大火烧了三个月。传说中的阿房宫从此成了一个代名词：数百年后，诗人杜牧写道，“楚人一炬，可怜焦土”，并告诫说，不怜惜百姓的君主，终将被后人所哀叹。",
  "chinese:thunder": "在中国的乡村，雷声是雷公的声音。雷公长着鸟喙和翅膀，手持锤和凿；他的搭档是电母，她用镜子照亮恶人，好让雷公一击不失。人们说，不孝或糟蹋粮食的人会遭天打雷劈。每当雷雨滚滚而来，孩子们就被叮嘱要把碗里的饭吃干净，要孝敬祖父母。",
  "chinese:birth": "明清时代，产妇分娩后要坐月子，避开风和冷水，喝加了姜的鸡汤。孩子满周岁时要抓周：毛笔、铜钱、印章、算盘和玩具刀剑摆在盘中，全家人凑上前去，看孩子会抓什么。在曹雪芹写于18世纪50年代的《红楼梦》里，小贾宝玉对这些一概不理，偏偏抓起了胭脂钗环，严厉的父亲便断定他将来不会有什么出息。读者为之一笑，而各家各户依旧看得同样仔细。",
  "chinese:death": "父母去世时，中国人家要披麻戴孝，在灵柩旁哭丧。道士或僧人诵经，焚烧纸钱和纸房子，好让逝者在另一个世界不致贫穷；到了头七，人们认为亡魂会最后一次回家看看。按照儒家礼制，儿子要为父母守丧三年，若在官任上便要辞官。悲伤并不掩藏，而是一项用心履行的义务。",
  // ── Shang ──
  "shang:hunt": "商王经常田猎，但出猎之前总要先问祖先。贞人在牛肩胛骨和龟甲上刻下问题：王今日在此地田猎，会不会有灾祸？事后有时还会刻上结果：获鹿若干，获野猪若干。一片著名的甲骨出自商朝最后一位王的时代，记载王捕获了一头巨大的野犀（兕），并因此受赐。田猎既是王家的乐事，也是军事操练，更是检验上天是否依然眷顾商王室的考验。",
  "shang:battle": "约公元前1200年，武丁王时期的甲骨记载，他的配偶妇好征集约一万三千兵力，西征羌人，这是甲骨中提到的规模最大的军队。她还领兵征讨过土方和夷人。她的墓中出土了刻有她名字的青铜钺。贞人一次又一次地占问她能否得到神灵佑助。对商人来说，战争有祖先一同参与，将军同时也是祭司。",
  "shang:gather": "在安阳周围的黄土河谷中，商人种植黍粟，每个季节贞人都要问同一个忧心的问题：我们会受年吗？被称为众人的劳动者在王家官员的督率下一同耕作，用石镰和蚌镰割下沉甸甸的穗子。一部分粮食被酿成酒献给祖先，因为人们相信祖先也会饥饿。丰收意味着神灵满意，王的占卜得到了好的回应。",
  "shang:ritual": "在殷都的王家宗庙里，贞人在洗净的龟腹甲上钻出凹槽，再把烧热的青铜棒按进去。龟甲伴着一声脆响裂开（“卜”字至今仍像那些裂纹）。王亲自观看裂纹：王占曰，吉。所问之事无所不包：降雨、战争、收成、牙痛、梦境。人们向帝和王室祖先献上牛、酒，有时还有俘虏。这是庄严的事业：请求逝者揭示明天。",
  "shang:rain": "安阳出土的一片最著名的甲骨，在癸卯日问道：今日会下雨吗？雨从西方来吗？从东方来？从北方来？从南方来？商人的生活全靠雨水落到他们的黍田里，贞人把问题刻向四方，仿佛转过身去依次眺望每一道地平线。还有许多甲骨记载王向河神和山神献祭，然后只是静静地等待云来。",
  "shang:flood": "商朝曾多次迁都，后世传统把原因归于黄河的洪水。约公元前1300年，盘庚王将都城迁到殷，百姓却不愿意走。《尚书》保存了他的讲话：他斥责，劝说，并保证说这次迁徙正是祖先自己的意愿。安阳的新都延续了两百多年。透过这些讲话，至今仍能听到普通百姓不愿离开家园、迁往高处时的恐惧。",
  "shang:wind": "商人相信风来自四方，每一方都有自己的神灵和名字。一片著名的甲骨列举了它们：东方曰析，其风曰协；南方曰因，其风曰凯，如此等等（四方风）。人们还认为风是至上神帝的使者，有时与凤用同一个字来写。每当大风刮起，贞人就会占问它是否会给王带来灾祸。",
  "shang:fire": "公元前1046年，周武王在牧野之战中打败了商朝最后一位君王帝辛。司马迁记载，帝辛逃回都城，登上鹿台，穿上缀满宝玉的衣服，自焚而死。六百年的商朝统治就在这场大火中终结。周人后来称他为暴君，但对商人来说，那是他们整个祖先与占卜的世界被焚毁的一夜。",
  "shang:thunder": "在商人看来，雨、风和雷都受帝的号令。帝是高居祖先之上的至上神，贞人会占问帝在某个月是否会令雷。人们可以请祖先代为祈求好天气，但帝本身很少直接受祭；他太高远，也太难以捉摸。当雷声在安阳平原上炸响时，商人听到的是一种连他们的王也只能占问、却无法号令的力量的意志。",
  "shang:birth": "甲骨保存了一次关于王室生育的真实占卜。甲申日，王问道：妇好娩，嘉？武丁王察看裂纹后说，若在丁日分娩，则嘉。几周之后，结果被刻了上去：不嘉，是个女孩。妇好本人后来还领兵出征。这片甲骨既显示出每一次生育的凶险，也显示出一个家族寄托于其上的期望。",
  "shang:death": "1976年，考古学家在安阳打开了未被盗扰的妇好墓，她约死于公元前1200年。她躺在髹漆的棺木中，随葬有468件青铜器、755件玉器、海贝、象牙杯、十六名殉人和六条狗。她死后，武丁王仍不断献祭，并占问她的灵魂。商人的葬礼盛大而令人生畏：逝者仍是强大的祖先，必须给予他们所需的一切。",
  // ── Shu ──
  "shu:hunt": "想象：深秋时节，在成都平原上方的山中，蜀国的军官们带着猎犬和弓箭出猎，在竹林中追逐野鹿。猎物供养驻军，同时也是为北方山路所做的演练，诸葛亮的大军终将要从那里行进。士兵们谈起被吴国夺走的故乡荆州，心想他们所效忠的汉室是否还能有一天重返长安。",
  "shu:battle": "219年，刘备的军队在定军山争夺汉中。法正瞅准时机，年过六旬的老将黄忠在震天的鼓声中从高处冲杀而下。魏将夏侯渊被斩。刘备夺取汉中，自立为汉中王。对蜀人来说，这证明了他们这个被群山隔绝的小国，依然能够打败北方。",
  "shu:gather": "蜀地以蜀锦闻名，所用的丝出自成都锦江沿岸，织成的锦缎在江中漂洗，直到色泽鲜亮。妇女们天刚亮便去采桑叶喂蚕。诸葛亮写道，如今国家决敌之资，唯仰锦耳。从桑园里采来的每一筐桑叶，在某种意义上都是复兴汉室之战的一部分。",
  "shu:ritual": "221年春，传来最后一位汉帝已被曹丕废黜的消息之后，刘备在成都以南的武担登上祭坛，祭告天地。他的诏书宣告汉室并未终结：他将承续汉的天命。对追随者来说，这是一次庄严的信仰之举，请求上天承认一个此时只据有一个群山环绕之州的王朝。",
  "shu:rain": "230年，魏将曹真经子午谷进攻蜀国。蜀国只能据守关隘，静待来敌。随后大雨开始下了，三十多天不曾停歇。悬在峭壁上的栈道被冲毁，魏军奉命撤回。在汉中，原本准备殊死一战的守军望着云层，觉得群山和上天都站在了自己这一边。",
  "shu:flood": "219年秋，关羽在汉水边围攻樊城。连绵大雨使河水暴涨决堤，扎营在低地的于禁七军被淹（水淹七军）。关羽的部下乘船而来；于禁投降，拒不投降的庞德被处死。有几个星期，整个中原为之震动。数月之后关羽本人也将被杀，但这场洪水始终是他最辉煌的时刻。",
  "shu:wind": "关于208年赤壁之战，史书只说当时东南风起，把黄盖的火船送进了曹操的船队。后来的《三国演义》却把这阵风归于蜀：诸葛亮登上南岸的祭坛，披发作法，借来了东风。这个传说表明蜀人希望怎样记住他们的军师：一个能与天对话的人。",
  "shu:fire": "222年，刘备为给关羽报仇而攻打吴国。他的军队在夏日酷暑中沿夷陵的林间连营数百里。年轻的吴军统帅陆逊按兵不动，随后派人持火把出击。营寨一座接一座地燃烧起来。刘备羞愤地逃往白帝城，再也没有回到成都。蜀国会把那场大火记作失去了一代士兵的那一夜。",
  "shu:thunder": "刘备寄身曹操门下时，曹操在酒席上对他说：天下英雄，唯使君与操耳。刘备大吃一惊，手中的筷子掉在了地上。后来的讲述又加上一笔：恰在此时雷声炸响，刘备便从容地把自己的惊慌推给了雷声（煮酒论英雄）。无论那雷声是否真有其事，这个故事都表明刘备当时活得多么危险，只能借着风雷来掩藏自己的野心。",
  "shu:birth": "刘禅，小名阿斗，207年出生，那时刘备已年近五十。次年在长坂，曹操的骑兵冲散了逃难的百姓，赵云抱着这个婴儿穿过乱军，把他救了出来。一个王朝的全部希望都系于这个婴儿身上。他在位四十年，但在263年向魏投降，后来还说自己在洛阳过得很快乐，并不思念蜀地。在他出生时，谁也猜不到这两种结局。",
  "shu:death": "234年，诸葛亮在最后一次北伐中病逝于五丈原军营。他生前要求简葬于汉中的定军山，墓穴只需容得下棺木，穿平常的衣服，不放任何珍宝。大军默默撤退。蜀地的百姓开始在田野间私下祭祀他，后来朝廷才准许为他立庙。直到今天，成都人仍在纪念他。",
  // ── Wei ──
  "wei:hunt": "魏国开国皇帝曹丕喜爱打猎，并颇为自豪地写过打猎之事。有一次他带着儿子曹叡出猎，射死了一头母鹿，便让儿子去射小鹿。曹叡放下弓哭着说：陛下已经杀了它的母亲，臣不忍心再杀它的孩子。曹丕深受感动，也放下了弓，从那以后便把这个孩子视为继承人。",
  "wei:battle": "208年冬，曹操率领庞大的北方军队顺长江而下，自以为南方唾手可得。在赤壁，他那些不习舟楫、又疫病缠身的士兵被周瑜和黄盖的火船击溃。曹操经华容道穿过沼泽撤退，泥泞深得让体弱的士兵在为战马铺草时被踩踏而死。一举统一中国的梦想就此破灭。",
  "wei:gather": "多年内战之后，北方空旷而饥荒遍地，士兵们靠桑葚充饥，甚至人相食。196年，曹操采纳枣祗的屯田之策：把流民和士兵安置在许昌附近的荒地上，发给他们耕牛和种子。第一年就收获了上百万斛粮食。收获这些粮食才是魏国真正的根基：吃得饱的军队才能打仗，吃得饱的家庭才能留下来。",
  "wei:ritual": "220年十月，最后一位汉帝献帝把皇位让给了曹丕。在繁阳筑起了受禅台。曹丕当着百官和军队登上高台，接受玉玺，燔柴祭天，宣告天命已归于魏。据说他事后说道：舜、禹之事，吾知之矣。记录这一仪式的石碑至今仍立在原址。",
  "wei:rain": "230年，魏国大司马曹真经子午谷向蜀国进军，意欲结束西线的战争。随后大雨来了：三十多天不曾停歇。峭壁上的栈道崩塌，粮草无法运送，朝中官员恳请皇帝召回大军。士兵们困坐在湿透的营帐里望着天空。这次出征最终作罢，曹真次年染病而死。",
  "wei:flood": "219年，将军于禁率七军驻扎在樊城城外。秋雨使汉水暴涨决堤，水位上涨时，他的士兵被困在一座座土丘上。关羽的战船前来收拾他们。于禁在效忠三十年之后投降了。他的同袍庞德拒不下跪，被处死。曹操说，他认识于禁三十年，没想到竟会如此。",
  "wei:wind": "225年，曹丕率领庞大的船队来到广陵的长江边，准备进攻吴国。冬日的风暴在江面上掀起巨浪，江水结冰，他的战船无法渡江。他站在岸边南望，叹息道：固天所以限南北也。于是班师而回。这场风暴与吴国的军队一样，让中国又分裂了半个世纪。",
  "wei:fire": "200年，在官渡，曹操的兵力不及袁绍，粮草也将耗尽。这时投奔过来的许攸告诉他袁绍的粮仓所在：乌巢。曹操亲率五千人连夜出发，打着袁军的旗号，背着成捆的柴草，烧毁了粮仓。袁绍大军随之崩溃。那一夜的大火决定了谁将统治中国北方。",
  "wei:thunder": "想象：一场夏日风暴笼罩着曹操的都城邺城。在铜雀台上，建安文人们暂停吟咏，闪电照亮城墙，雷声滚过平原。官员们低声议论着征兆：上天是在嘉许曹氏，还是在警告它？在营房里，士兵们只是抱住脑袋，等着大雨过去，一如既往。",
  "wei:birth": "曹冲约生于196年，是曹操最钟爱的孩子。大约五岁时，孙权送来一头大象，这孩子先看大象把船压到水下多深并做上记号，再往船上装石头直到同一记号，从而称出了大象的重量（曹冲称象）。曹操曾想立他为继承人。208年，曹冲病逝，年仅十二岁。曹操对其他儿子们说：此我之不幸，而汝曹之幸也。",
  "wei:death": "220年去世之前，曹操留下遗嘱：敛以时服，墓中不放金玉珍宝，驻军不得离开岗位前来奔丧。天下仍处于战乱之中，他不愿浪费财力。2009年，考古学家在安阳确认了他的陵墓高陵，墓中果然随葬品简朴：刻着他兵器名称的石牌，以及一具约六十岁男子的遗骨。",
  // ── Wu ──
  "wu:hunt": "吴主孙权喜欢骑马出去射虎。有一次一只老虎扑上来，爪子抓到了他的马鞍。老臣张昭严厉地劝谏他：为人君者应当驾驭英雄，而不是与猛兽竞逐。孙权道了歉，却始终戒不掉；他特意造了一辆开有射孔的车，好坐在车里射虎。他的哥哥孙策就是独自打猎时遇害的，朝中上下始终没有忘记。",
  "wu:battle": "208年冬，曹操庞大的北方船队顺长江而下。吴国许多人主张投降。孙权拔剑砍下案角，说再有人敢言投降，就与此案同。年仅三十三岁的周瑜与刘备一起，在赤壁统率联军船队。黄盖燃烧的火船撞进了用铁索连在一起的敌船。对吴国来说，这一天证明了南方可以独立自存。",
  "wu:gather": "想象：在江东湿润的田野里，吴国的人家插秧，收获时蹚过水田，妇女们则在温暖的月份里养蚕。数以万计的北方人为躲避战乱逃到这里，原有的南方人和新来的人学会了并肩耕种。每一船运往建业的稻米，都养活着守卫漫长江防线的士兵。",
  "wu:ritual": "229年，孙权终于在武昌称帝。官员们奏报祥瑞：有人看见了黄龙和凤凰，于是他把年号定为黄龙。他在祭坛上祭天，宣告天命也已降临南方。对于长期被北方人轻视为沼泽之民的人们来说，这是一个庄严的宣告：上天也看见了他们。",
  "wu:rain": "222年，刘备的复仇大军深入吴境扎营。年轻的统帅陆逊拒不出战。好几个月里，他手下的将领，许多比他年长、出身也更高贵，都怒斥他胆怯。陆逊只是等待，从春雨等到夏日酷暑，直到蜀军士兵在林中营寨里变得疲惫松懈。他在等待局势改变，局势一变，他便出击了。",
  "wu:flood": "想象：某年夏天，长江连续数周上涨，江水浑黄湍急，淹没了建业周围的低洼田地。吴国农民把船拖到家门口，把老人和米缸搬上堤坝。驻军也被派来往筐里装土。水退之后，他们又在新淤的泥土上播种，像江东人一向所说的那样：江水夺走的，江水也会还回来。",
  "wu:wind": "想象：一场夏日风暴在武昌附近的长江上袭击了一支吴国船队。狂风撕扯着船帆，巨大的楼船倾侧摇晃；桨手们拼命划向岸边，其他人则向江神祈祷。吴国凭水立国，它的水手们知道江水翻脸有多快。风停之后，他们清点失踪的船只，并到江边的神祠献祭。",
  "wu:fire": "222年夏，刘备的军队沿夷陵林木茂密的山谷连营数百里，营寨都是木造的。等待了数月的陆逊下令每名士兵带一捆芦苇，放火烧营。火势从一座营寨蔓延到另一座。蜀军四十多座营寨被攻破，刘备逃走。曾被年长将领们嘲笑的年轻书生陆逊，成了吴国的英雄。",
  "wu:thunder": "想象：在江东炎热的夏天，风暴在长江上空迅速积聚，到午后便倾泻而下。吴国的村民们赶紧把水牛赶回家，关上窗板，在雷神像前点香。水手们把船系好。孩子们被告知，雷会寻找做坏事的人，好人没什么可怕的；不过大人们抬头望天时，还是有点紧张。",
  "wu:birth": "《三国志》记载，武将孙坚的妻子吴夫人怀长子孙策时，梦见月亮进入怀中；怀孙权时，又梦见了太阳。孙坚说，日月是阴阳之精，这是极贵之象，他的子孙将会兴盛。两个儿子长大后都统治了南方，孙权建立了吴国。",
  "wu:death": "200年，平定江东的孙策在打猎时遭到伏击，伤重而死，年仅二十五岁。临终前，他把印绶交给十八岁的弟弟孙权：举江东之众，决机于两陈之间，与天下争衡，卿不如我；举贤任能，各尽其心，以保江东，我不如卿。孙权哭泣不止。张昭对他说，现在不是哀哭的时候；他为孙权换上衣服，扶他上马，出去巡视军队。",
  // ── Zhu Xi's Legacy ──
  "zhu-xis-legacy:hunt": "想象：南宋时，在福建的山中，一户读书人家在冬天带着网和猎犬出去捕野兔和雉鸡。年轻人读过《礼记》，知道春天鸟兽孕育时不可打猎，也不可四面合围一群野兽。他们的老师是朱熹的门人，提醒他们即使在打猎时也要格物，并保持一颗仁爱之心。",
  "zhu-xis-legacy:battle": "1279年，在广东外海的崖山，南宋最后约一千艘战船用铁索连在一起，迎战蒙古人统率的元朝水军。经过数周的围困和缺水，阵线崩溃了。丞相陆秀夫是一位受朱熹忠义之教熏陶的儒士，他背起八岁的皇帝跳入大海。许多官员和家眷随之赴死。宋代士人长久地把这一天记作一个文明的死亡。",
  "zhu-xis-legacy:gather": "1171年，福建五夫一带发生饥荒之后，朱熹设立了社仓。丰年时，村民们把粮食存入社仓；青黄不接的春季，他们以低息借粮，秋收后偿还。这是把儒家伦理付诸实践：邻里互助，不必等待官府。朱熹奏请朝廷在各地推广，社仓于是遍及全国。",
  "zhu-xis-legacy:ritual": "1195年，宰相韩侂胄迫害所谓的伪学，朱熹起草了一份长篇奏章来弹劾他。他的学生们恳求他不要递上去。最后朱熹取出蓍草，用《易经》占卜，得到的是遯卦：退避。他默默烧掉了草稿，自号遯翁，意思是退隐的老人。在他看来，占卜不是巫术，而是对天道规律的郑重请教。",
  "zhu-xis-legacy:rain": "1179年，朱熹出任庐山脚下的南康知军，次年遭遇旱灾。作为地方长官，他按照惯例率众祈雨，同时也减免赋税、开仓放粮、组织赈济，并上书请求援助。他写道，为政者必须把百姓的饥饿当作自己的饥饿。他和属官们每天走过干裂的田野，一边等待云来，一边做人力所能及的事。",
  "zhu-xis-legacy:flood": "想象：南宋某年夏天，一股山洪冲下朱熹曾经讲学的武夷附近的山谷。村民们逃往山坡，怀里首先抱着的是祖先的牌位。事后，当地的士人组织修补堤坝、分发粮食，并朗读老师的著作：真正的学问必须体现在帮助乡邻之中。",
  "zhu-xis-legacy:wind": "想象：一场台风从海上吹到福建沿海，掀翻了建阳房屋的屋顶，那里的宋代刻工正在雕刻朱熹注疏的书版。刻工们急忙用油布盖住书版。事后士人们在镇上走了一圈，其中一人说，风也不过是流动的气，循着它的理而行，一颗平静的心可以经受住任何风暴。",
  "zhu-xis-legacy:fire": "南宋都城临安，即今天的杭州，是一座木屋密布的拥挤城市，大火一次又一次地袭击它。城中各处立有望火楼，一见烟起，由士兵组成的救火队便提着水桶、斧头和梯子冲出去。信奉朱熹学说的官员们追问，这些火灾是否是上天对失政的警告，并敦促皇帝反省自身，救济无家可归的人。",
  "zhu-xis-legacy:thunder": "朱熹的学生曾问他雷是什么。据《朱子语类》记载，他回答说，雷是阴阳二气相搏：阳气被困而迸发，便成了雷，就像放炮一样。他并不完全否认鬼神，但他教导说，世界依循理而运行，是可以被理解的。对他的门人来说，雷雨令人敬畏，但也是可以冷静研究的对象。",
  "zhu-xis-legacy:birth": "朱熹1130年生于福建尤溪，当时中国北方已被女真人的金朝占领，他的家人逃到了南方。后来的门人说，他右脸颊上有七颗痣，排列如北斗。他的父亲朱松是一名小官，反对与金议和。那时谁也不会知道，这个孩子将在七百年间塑造中国、朝鲜和日本的思想。",
  "zhu-xis-legacy:death": "1200年朱熹去世时，他的学说仍被当作伪学禁止（庆元党禁）。朝廷警告官员不得聚集参加他的葬礼，但仍有近千人来到建阳，按照他在《朱子家礼》中写下的礼仪为他下葬。词人辛弃疾在祭文中写道：所不朽者，垂万世名。几十年之内，他的注疏便成了科举考试的依据。",
  // ── Japanese ──
  "japanese:hunt": "1193年，新任将军源赖朝在富士山麓举行了盛大的围猎（富士の巻狩り）。武士们一连数周把鹿和野猪赶向射手，他的儿子赖家第一次射中猎物，被庆贺为神明的征兆。最后一夜，曾我兄弟祐成和时宗冒雨潜入营地，杀死了十八年前杀害他们父亲的工藤祐经。他们复仇的故事至今仍在歌舞伎舞台上演出。",
  "japanese-early:battle": "1185年，平氏与源氏的船队在下关海峡的坛之浦（壇ノ浦）交战。潮流转而对他们不利时，平氏明白大势已去。六岁的安德天皇的外祖母把他抱在怀里；他问要去哪里，她告诉他，波涛之下也有都城。他们一同沉入海中。《平家物语》开篇便是寺院的钟声，诉说诸行无常。",
  "japanese:gather": "每年六月，日本的稻作村落都要插秧（田植え）。被称为早乙女的妇女们穿着同样的和服、戴着草帽，在灌满水的稻田里排成一行弯着腰，用手插下秧苗；田埂上的鼓手和笛手演奏插秧歌（田植え歌），既为了合上节拍，也为了取悦田神。秋收时，头一批稻谷要献给神社。收割稻谷从来不只是劳作：它也是与神同庆的节日。",
  "japanese:ritual": "在日本最神圣的伊势神宫，供奉太阳女神天照的正殿每二十年都要用新的桧木重建一次，称为式年迁宫，这一传统可追溯到690年。迁座之夜，身穿白衣的神官们在黑暗与寂静中，把藏在绢幕之下的神镜从旧殿抬到新殿。这是祈愿国土焕然一新的祷告，也是代代相传的承诺。",
  "japanese-early:rain": "824年，干旱使京城焦渴，朝廷请两位高僧在京都的神泉苑祈雨。传说僧人守敏把所有龙神都关进了一个瓶子里，但空海找到了一位逃脱的龙神，即善女龙王，并从喜马拉雅山把她请来。大雨在日本各地下了三天。农民们长久以来都在村里的池塘边举行祈雨仪式（雨乞い），擂着鼓，等待云来。",
  "japanese:flood": "甲斐的釜无川几乎年年泛滥，毁坏稻田平原。16世纪40年代，战国大名武田信玄开始修建一套由错落的堤防、石质丁坝和改道河渠组成的系统，把洪水引开。在堤防后定居的村民得以免除赋税，作为交换，他们要负责守护堤防。信玄堤的一部分至今仍在保护着甲府，山梨的人们说起他时仍满怀感激。",
  "japanese:wind": "1281年夏，蒙古人统率的元朝四千多艘战船聚集在博多湾外。几周以来，武士们一直凭借沿岸修筑的石墙与他们作战。随后在八月中旬，一场大台风袭来，击沉了大部分船只。日本的寺院和神社已经祈祷了好几个月，人们称之为神风：这证明众神在守护这片土地。如释重负之感像那场风暴本身一样席卷了全国。",
  "japanese:fire": "1657年正月十八日，江户本乡起火，在强风的推动下烧过了一座因整个冬天无雨而干燥的城市。三天之内，明历大火烧毁了都城的大部分，包括江户城的天守阁，死者或达十万人。传说起因是一件受了诅咒的长袖和服在寺院里被焚烧（振袖火事）。江户重建时开辟了防火带，拓宽了街道，并设立了消防队。",
  "japanese-early:thunder": "大学者菅原道真于901年遭冤贬谪，903年死于大宰府。不久，他的政敌们接连死去，930年，雷电击中了皇宫的清凉殿，劈死了几名朝臣。朝廷相信是他愤怒的冤魂化作了雷神。他被赦免，死后追赠官位，被奉为天神，如今是学问之神。人们在雷雨时念叨“桑原，桑原”，因为据说雷电从不落在他从前的庄园桑原。",
  "japanese:birth": "怀孕第五个月的戌日，日本的准妈妈会去东京水天宫这样的神社参拜，并系上长长的白色腹带（岩田带），因为狗生产顺利，幼崽多能存活。分娩是危险的，家人们虔诚祈祷。满月之后，婴儿被抱到当地神社初次参拜（お宮参り），家人请求神明守护这个孩子将要度过的一生。",
  "japanese:death": "日本的葬礼大多遵循佛教习俗。家人守夜（通夜），僧人为逝者取一个新的法名（戒名），遗体随后火化。接着是拾骨（骨上げ）：两位亲属一起用长筷子把骨头夹进骨灰坛，从脚部开始，好让逝者不至于头朝下。每年夏天的盂兰盆节（お盆），人们点起灯笼、跳起舞蹈迎接祖先回家，再用篝火把他们送回。",
  // ── Yamato ──
  "yamato:hunt": "《古事记》记载，5世纪的雄略天皇带着身穿青衣、系着红带的朝臣们到葛城山打猎。山谷对面来了另一支队伍，与他的队伍一模一样。天皇大怒，喝问对方首领的名字，那陌生人回答说，他是一言主，一言便定善恶的神。雄略天皇肃然起敬，躬身献上自己的刀、弓和随从们的衣服，神则一路护送他回家。",
  "yamato:battle": "663年，大和派出一支庞大的船队，去帮助复兴朝鲜已经灭亡的百济。在白江口，日本称为白村江，他们遭遇了唐朝和新罗的水军。《日本书纪》记载，大和的船只乱哄哄地冲上前去，被夹在敌军阵线之间；片刻之间许多人溺死，江水都被染红了。朝廷害怕遭到入侵，在九州各地修筑了石城和烽火台。",
  "yamato:gather": "《万叶集》的第一首歌据说出自雄略天皇之手。他在山丘上遇见一位采摘春菜的少女：提着篮子，漂亮的篮子；拿着铲子，漂亮的铲子；在这山坡上采菜的姑娘啊，告诉我你的家，告诉我你的名字。早春采摘嫩菜是大和的时令习俗，这首歌捕捉到了它的明亮：新芽、开阔的天空，新的一年正在开始。",
  "yamato:ritual": "中国的《魏志》记载了3世纪的倭国，由女王卑弥呼统治，她事鬼道，能惑众。倭人在出行或做任何事情之前，都要灼骨观察裂纹，以占卜吉凶。在日本，这演变成了太占：把鹿的肩胛骨放在樱树皮上灼烧，用它的裂纹询问众神将要发生什么。",
  "yamato:rain": "642年，大和遭遇严重旱灾。《日本书纪》记载，权臣苏我虾夷命人诵读佛经、焚香，却只下了一点小雨。随后皇极天皇来到南渊的河源，跪下向四方礼拜，向上天祈祷。雷声隆隆，大雨下了五天，遍及全国。农民们称颂她是至德的天皇。",
  "yamato:flood": "《日本书纪》记载，仁德天皇修筑茨田堤以抵御淀川的洪水，但有两处缺口总是决堤。他梦见神要求献祭两个人。一个名叫强颈的人被投入水中。另一个名叫衫子的人则把两个葫芦扔进水里，说：你若真是神，就让它们沉下去；如果浮着，你就是假的。葫芦浮了起来，他活了下来，堤坝也保住了。",
  "yamato:wind": "大和派往唐朝的遣唐使乘坐脆弱的船只渡海，许多人死于风暴。中国僧人鉴真于742年受邀前往日本；五次航行都因台风和船难而失败，他在途中双目失明。753年第六次尝试时，他终于抵达日本，并在奈良创建了唐招提寺。同一支船队中的使者阿倍仲麻吕被风吹离航道，再也没有回到故乡。",
  "yamato:fire": "《日本书纪》记载，670年四月的一个半夜，圣德太子创建的法隆寺起火，一座建筑也没有留下。随后大雨和雷电接踵而至。寺院在此后几十年间得到重建，如今它的木造殿堂是世界上现存最古老的木构建筑之一，依然承载着那些不愿让它消失的人们的虔诚。",
  "yamato:thunder": "《日本灵异记》记载，雄略天皇曾命侍从栖轻去把雷神请来。栖轻举着红旗骑马出去，以天皇的名义呼唤雷神降临。闪电落在一座山丘上，栖轻便用轿子把雷神抬了回来。天皇被它的光芒吓坏了，命人把它送了回去。那个地方被命名为雷丘，至今仍在飞鸟。",
  "yamato:birth": "《古事记》和《日本书纪》中的传说称，神功皇后率军渡海远征朝鲜时正怀着身孕。为了把分娩推迟到归来之后，她在腰间系上了石头。她回国后在筑紫生下了后来的应神天皇，他后来被奉为战神八幡。她的那些石头称为镇怀石，几百年来一直被大和的母亲们尊为保佑顺产的护符。",
  "yamato:death": "大和的统治者被葬在巨大的锁孔形坟丘（前方后圆坟）中，例如被认为是仁德天皇陵的那座，它是世界上最大的坟墓之一。坟丘的斜坡上排列着称为埴轮的陶土人像。《日本书纪》记载，日叶酢媛皇后去世时，工匠野见宿祢提议用陶土人像代替活埋仆从，天皇同意了。一排排埴轮武士、马匹和房屋守护着逝者。",
  // ── Sengoku Daimyo ──
  "sengoku-daimyo:hunt": "织田信长喜爱鹰狩（鷹狩り）。《信长公记》记载他一次又一次带着鹰骑马出猎，他还曾举行过一次有数百名鹰匠参加的大猎。猎场也让领主得以巡视领地、考验部下、向农民展示自己的权势。同样酷爱鹰狩的德川家康说，鹰狩能强健身体，还能让他看到农民的生活。对战国大名来说，打猎既是休息，也是谋略。",
  "sengoku-daimyo:battle": "1561年，在第四次川中岛之战中，武田信玄和上杉谦信的军队在晨雾中相遇。传说谦信单骑冲入信玄的本阵，挥刀砍了他三次；信玄依然坐着，用铁制军扇挡住了刀。那一天双方都损失了数千人。这对宿敌在十年间交战五次，始终未分胜负，但他们一对一交锋的故事流传了好几百年。",
  "sengoku-daimyo:gather": "1588年，丰臣秀吉颁布刀狩令：日本所有农民都必须交出刀剑、弓箭、长枪和火枪。法令说，这些金属将被熔化，铸成他在京都建造的大佛所用的钉子，这样农民今生来世都能得救。实际上，它结束了农民也作为战士参战的一个世纪。秀吉收缴了武器，也把整个国家收归一手。",
  "sengoku-daimyo:ritual": "上杉谦信相信自己是佛教战神毘沙门天的化身，军旗上写着一个“毘”字。每逢大战之前，他都要把自己关在春日山城的毘沙门堂里，祈祷斋戒数日。许多大名还养着军配者，即用占卜选择吉日和方位的军师。战前求问神明，就像检查武器一样自然。",
  "sengoku-daimyo:rain": "1560年，今川义元率领约两万五千大军向京都进发。只有几千人的织田信长在热田神宫祈祷后，埋伏在桶狭间上方的山中。正午前后，一场猛烈的暴雨夹着冰雹倾泻在山谷上。雨过天晴，信长冲进了正在休整的义元营地，义元被杀。一场暴雨之间，天下就变了。",
  "sengoku-daimyo:flood": "1582年，丰臣秀吉围攻建在沼泽地中的备中高松城。他没有强攻，而是让部下在约十二天内筑起一道长长的土堤，并引河改道；梅雨季的雨水灌满了平原，城池变成了一座孤岛（水攻め）。为了保全守军，城将清水宗治乘一只小船划出，跳完最后一支舞，当着两军的面自尽。",
  "sengoku-daimyo:wind": "想象：八月里，一场台风在收获前夕横扫了某个战国领地的稻田平原。事后领主的家臣们骑马走遍各村，清点被吹倒的田地，城中的粮仓向最饥饿的人开放。村长们恳求减免年贡。四面边境都有敌人，大名知道一场歉收可能和一场败仗一样危险，于是他把稻米送往南方，换取和平。",
  "sengoku-daimyo:fire": "1582年六月二日黎明前，明智光秀的军队包围了京都的本能寺，织田信长正带着少量护卫住在那里。据记载，信长得知来袭者是谁之后说：是非に及ばず（无可奈何）。他先用弓和长枪奋战，然后在寺院燃烧之际退入内室。他的遗体始终没有找到。那个几乎统一了日本的人，就这样消失在火焰之中。",
  "sengoku-daimyo:thunder": "九州大友氏的家臣立花道雪在一场雷雨中于树下休息时，雷电劈了下来。传说他拔出名刀千鸟，斩杀了雷电中的雷神。他从此腿脚不便，但保住了性命，那把刀则被改名为雷切。在战事无休无止的时代，战国武士们喜爱这样一个连天空也能与之搏斗的故事。",
  "sengoku-daimyo:birth": "1593年，淀殿生下一个儿子，名叫拾，后来改名丰臣秀赖。他的父亲丰臣秀吉已经五十七岁，此前失去了第一个儿子。他欣喜若狂，给婴儿写了许多充满爱意的信，后来还逼迫自己的外甥兼继承人自尽。临终前，他让各大名发誓保护这个孩子。1615年大坂城陷落，秀赖死时年仅二十二岁，寄托在他身上的全部希望也随之破灭。",
  "sengoku-daimyo:death": "武田信玄于1573年在出征途中去世，可能是病逝。据《甲阳军鉴》记载，他的遗嘱命令将他的死讯保密三年，以免敌人乘虚而入。一个替身坐在他的位置上，书信仍盖着他的印章发出。据说他的遗体身披铠甲沉入了诹访湖，也有说悄悄葬在了惠林寺。他的家臣们默默哀悼，守着这个秘密。",
  // ── Koreans ──
  "koreans:hunt": "1404年，朝鲜太宗带着鹰犬出猎，在追鹿时从马上摔了下来。他爬起来后对侍从说的第一句话是：不要让史官知道。但史官早已听到，《朝鲜王朝实录》（조선왕조실록）既记下了这次落马，也记下了国王不许记录的命令。对朝鲜人来说，这个故事成了一个令人自豪的象征：连国王也无法扭曲的秉笔直书。",
  "koreans:battle": "1597年，刚刚在遭受拷打和贬黜之后恢复指挥权的李舜臣（이순신）只剩下十三艘战船。他上书国王：今臣战船尚有十二。在潮水如江河般咆哮的鸣梁海峡（명량），他迎战约133艘日本战舰。其他战船犹豫不前时，他让旗舰顶着急流坚守不退；随后潮水转向，敌阵崩溃。朝鲜人至今称之为鸣梁大捷的奇迹。",
  "koreans:gather": "在朝鲜的深山里，被称为采参人（심마니）的人们寻找野山参（산삼）。他们恪守严格的禁忌：事先斋戒净身、分开睡觉、说秘密的行话，并向山神（산신）祈祷。当有人终于发现红色的参籽时，他便高喊“심봤다！”（看到参了！），其他人随即跪下。他们用鹿角做的签子慢慢把参挖出来，不让任何一根须根折断。",
  "koreans:ritual": "在首尔（서울）的宗庙（종묘），朝鲜（조선）历代国王和王后的神位在宗庙祭礼（종묘제례）中受到祭祀，这一王室祭祖仪式已延续了六个世纪。身穿祭服的后裔们按严格的次序献上食物和酒，宫廷乐师们演奏缓慢庄重的宗庙祭礼乐（종묘제례악），伴以编磬和编钟。它并不悲戚：这是与祖先的一场庄严对话，请他们守护这片土地。",
  "koreans:rain": "1441年，世宗（세종）在位期间，朝鲜制造了标准的雨量器（측우기）：一种青铜圆筒，放置在各道，用来精确测量降雨量，比欧洲早了大约两个世纪。遇到旱灾时，国王仍要主持祈雨祭（기우제），世宗本人也曾为百姓斋戒。但有了雨量器，官员便能根据实际测量来安排赋税和赈济。这是祈祷与科学的结合，二者都着眼于农民的田地。",
  "koreans:wind": "1653年，一艘名为斯佩韦尔号（Sperwer）的荷兰东印度公司船只在济州岛（제주도）外海被风暴打碎。三十六名水手上了岸。朝鲜官府把他们送到首尔（서울），一关就是十三年；朝鲜（조선）不许外人离开。1666年，亨德里克·哈梅尔和另外七人乘船逃往日本，他的日记让欧洲第一次详细了解了朝鲜。一场风暴打开了一扇两国人民都紧闭着的门。",
  "koreans:thunder": "想象：一个夏日午后，在朝鲜（조선）的一个村庄，一场突如其来的风暴降临在稻田上。祖母把孩子们叫进屋里，告诉他们雷声是雷神（뇌신）在寻找对父母不孝的人。雨点敲打着茅草屋顶，孩子们一动也不敢动；雷声远去后，祖母笑了，给了他们烤栗子。",
  "koreans:birth": "朝鲜人家里生了孩子，就在门口挂一根叫作禁绳（금줄）的草绳：生男孩挂红辣椒和木炭，生女孩挂松枝和木炭。它告诉邻居三周内不要进门，以免带来疾病。家人向产神奶奶（삼신할머니）祈祷。满一百天时要过百日（백일），周岁时则有抓周（돌잡이），孩子从摆满物品的桌上选择自己的未来。",
  "koreans:death": "在朝鲜的儒家葬礼上，服丧者身穿粗麻，在规定的时刻哭喊“哀告，哀告”（곡）。灵柩放在一种叫作丧舆（상여）的彩色灵车上，饰以纸花；领唱者摇着铃唱起丧舆歌（상엿소리），抬棺人齐声应和：我走了，离开这个世界。逝者被葬在依风水选定的山坡上，家人每逢忌日都要举行祭祀（제사）。",
  // ── Choson (Gojoseon) ──
  "choson:hunt": "想象：在辽东（요동）和半岛北部的森林中，古朝鲜（고조선）的人们用木头和兽角制成的弓猎鹿和野猪，有些箭头是青铜的。一个年轻人第一次猎获的野兽被抬回家，分给村里的各户人家。一位长老把它的血献给山神，并为这头野兽说几句话，好让森林继续馈赠。然后大家在星空下饱餐一顿。",
  "choson:battle": "公元前109年，汉武帝派大军从陆路和海路进攻卫满朝鲜（위만조선）。右渠王（우거왕）据守有城墙的都城王险城（왕검성）近一年；汉军将领彼此争执，久攻不下。但在城内，主张议和的大臣们终于在公元前108年杀死了国王。即便如此，大臣成己（성기）仍坚持抵抗，直到他也被杀。城破之后，汉朝设立了郡县。这个王国不是亡于战场，而是亡于内部。",
  "choson:gather": "想象：在朝鲜的青铜时代，数百名村民聚集在河边，为一位受人尊敬的首领立起一座支石墓（고인돌）。他们用浸水的木楔从崖壁上劈下一块巨大的盖石，用绳索拉着它在圆木滚轴上前进，一边有节奏地唱歌一边齐心拉动，再通过土坡把它滑到竖立的石柱上。朝鲜半岛有数万座支石墓，数量居世界前列。",
  "choson:ritual": "在建国神话中，檀君王俭（단군왕검）既是祭司又是君王：檀君可能意为侍奉上天的人，王俭则意为统治者。江华岛（강화도）摩尼山上有一座石坛，名叫堑星坛（참성단），传说檀君曾在那里祭天。朝鲜人至今仍在那里为国家庆典点燃圣火，并在每年10月3日庆祝开天节（개천절），即天门开启之日。",
  "choson:rain": "《三国遗事》（삼국유사）记载，天帝之子桓雄（환웅）降临太白山（태백산），带来了三千随从和三位神官：风伯（풍백）、雨师（우사）和云师（운사）。他通过他们掌管谷物、生命、疾病和刑罚。对一个农耕民族来说，立国始于天气之神亲自降临人间，和他们一同等待雨水。",
  "choson:flood": "想象：某年夏天大雨不断，大同江（대동강）水位暴涨，冲进了古朝鲜（고조선）聚落周围的田地。村民们把陶器、种粮和青铜短剑搬到山城上，在那里躲避了好几天。水退之后，长老们聚集在老首领的支石墓前，感谢无人溺死，各家各户则一同下山，重建他们的半地穴式房屋。",
  "choson:wind": "想象：一场巨大的秋季风暴从草原刮下来，横扫辽东（요동）平原。在古朝鲜（고조선）的村落里，狂风掀掉了半地穴房屋的茅草顶，吹倒了黍田。人们相信这是随桓雄（환웅）一同降临的风伯（풍백），在提醒他们上天的威力。巫师在村边的神树上挂起祭品，大家等待天空重新平静下来。",
  "choson:fire": "想象：公元前108年，王险城（왕검성）的最后日子里，随着汉军加紧围攻，城墙上燃起了火。城内的人家把铜镜和短剑埋在屋子的地下，希望将来能回来取。两千年后，考古学家会发现这样的窖藏。朝鲜（조선）的人们望着烟雾在都城上空升起，不知道投降带来的会是和平还是奴役。",
  "choson:thunder": "想象：一场夏日风暴袭击了古朝鲜（고조선）的腹地，闪电劈开了埋葬祖先的山脊上的一棵老橡树。村民们惊恐地聚在一起：桓因（환인）所在的上天是在对他们发怒吗？巫师摇着铃铛、舞着青铜镜跳起舞来，把镜子的光闪向天空，并献上黍米和酒。到了早晨风暴已经过去，那棵劈开的橡树被缠上草绳，成了一棵神树。",
  "choson:birth": "《三国遗事》（삼국유사）记载，一只熊和一只老虎恳求桓雄（환웅）让它们变成人。他给了它们艾草和二十瓣大蒜，让它们一百天不见阳光。老虎放弃了；熊坚持了下来，变成了一个女人，名叫熊女（웅녀）。她在檀树下祈求孩子，桓雄便娶了她。他们的儿子就是檀君（단군），按照传统说法，他于公元前2333年建立了朝鲜（조선）。一个民族就诞生于她的耐心。",
  "choson:death": "古朝鲜（고조선）和朝鲜青铜时代的人们把死者葬在支石墓（고인돌）和石棺墓中，常常随葬琵琶形铜剑（비파형동검）和精美的铜镜。高敞（고창）、和顺（화순）和江华（강화）的支石墓群如今已是联合国教科文组织世界遗产。传说檀君（단군）本人并没有死，而是在1908岁时隐入山中，成了那里的山神（산신）。",
  // ── Mongols ──
  "mongols:hunt": "初冬时节，蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）军队要举行盛大的围猎，称为“涅儿格”（nerge）。志费尼描述过它：骑兵们散开成一个宽达好几天路程的大圈，在旗帜和鼓声的指挥下用数周时间慢慢收拢，直到所有猎物都被困在人圈之中。任何让野兽逃脱的士兵都会受罚。可汗先射，然后是诸王，然后是士兵；最后剩下的野兽被放走。这既是盛宴，也是对草原的清点，更是战争的预演。",
  "mongols:battle": "1241年4月，拔都（ᠪᠠᠲᠤ / Бат）和速不台（ᠰᠦᠪᠡᠭᠡᠳᠡᠢ / Сүбээдэй）统率的蒙古军队在莫希附近的绍约河与匈牙利国王贝拉四世交战。黎明时分，拔都的部下用投石机强夺桥梁，速不台则在下游秘密渡河。匈牙利人被困在车阵营地里；蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人在包围圈上故意留了一个缺口，敌人从缺口逃出时，他们便沿着道路追杀。对草原骑手来说，这证明了西方没有什么能阻挡他们。",
  "mongols:gather": "1206年春，蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）各部落聚集在斡难河（ᠣᠨᠠᠨ / Онон）源头，召开盛大的忽里勒台（大会）。九斿白纛竖了起来，铁木真（ᠲᠡᠮᠦᠵᠢᠨ / Тэмүжин）被推举为成吉思汗（ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ / Чингис хаан），成为《蒙古秘史》（ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠨᠢᠭᠤᠴᠠ ᠲᠣᠪᠴᠢᠶᠠᠨ / Монголын нууц товчоо）所说的一切毡帐之民的统治者。互相仇杀的部落成了一个民族。此后每年夏天，牧民们都会再次聚会，举行赛马、摔跤和射箭，这些竞技延续至今，就是那达慕（ᠨᠠᠭᠠᠳᠣᠮ / Наадам）。",
  "mongols:ritual": "1254年，方济各会修士鲁布鲁克的威廉在蒙哥汗（ᠮᠥᠩᠬᠡ / Мөнх хаан）的宫廷里看到，可汗做任何事之前都要先请教一块羊肩胛骨。占卜者把骨头放在火中烧到开裂；如果裂纹沿纵向笔直延伸，可汗就会行动；如果是横向的，他就不做。蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人崇拜长生天（蒙克腾格里），通过击鼓召唤神灵的萨满（孛额）与之沟通。",
  "mongols:rain": "蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人相信，有些萨满能用一种叫作札答石的神奇牛黄呼风唤雨。史书记载，1232年在三峰山，拖雷（ᠲᠣᠯᠤᠢ / Тулуй）疲惫的军队面对兵力远超自己的金军，天降大雪，三天不停；后来的记载把这归功于一位持石作法的人。冻僵的金军崩溃了。对普通牧民来说，等待雨水意味着盯着牧草，祈祷春天在牲畜饿死之前到来。",
  "mongols:wind": "1274年和1281年，忽必烈汗（ᠬᠤᠪᠢᠯᠠᠢ / Хубилай хаан）两次派遣由蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人、汉人和高丽人组成的船队征讨日本。两次都遇上了风暴。1281年，在博多湾激战数周之后，一场台风袭来；一艘又一艘船，其中许多是用内河船只仓促改造的，相互撞碎沉没，数以万计的人溺死或被遗弃在岸上。对于从高丽一直征服到匈牙利的蒙古人来说，这是一个苦涩的教训：大海和风并不听从可汗。",
  "mongols:fire": "1220年，成吉思汗（ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ / Чингис хаан）攻占布哈拉。伊本·阿西尔和志费尼记载，他骑马进入大清真寺，登上讲坛，对民众说：我是上帝的惩罚；如果你们没有犯下大罪，上帝就不会派我来。随后这座木屋之城被焚毁，只剩下砖砌的清真寺和宫殿。对蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人来说，这是作为战略的恐怖；对布哈拉来说，这是一个世界的终结。",
  "mongols:thunder": "欧洲使节们惊讶于蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人对雷的恐惧。柏朗嘉宾（1246年）和鲁布鲁克的威廉（1254年）写道，雷雨来临时，蒙古人会把外人赶出帐篷，用黑毡裹住自己，躲到雷雨过去。被雷击死的人，连同他的帐篷和财物，都必须从两堆火之间穿过以示净化。蒙古法令还禁止在夏天到河里洗澡或洗衣服，以免触怒雷神。",
  "mongols:birth": "蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人的《秘史》（ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠨᠢᠭᠤᠴᠠ ᠲᠣᠪᠴᠢᠶᠠᠨ / Монголын нууц товчоо）记载，铁木真（ᠲᠡᠮᠦᠵᠢᠨ / Тэмүжин）出生在斡难河（ᠣᠨᠠᠨ / Онон）畔的迭里温孛勒答黑（ᠳᠡᠯᠢᠭᠦᠨ ᠪᠣᠯᠳᠠᠭ / Дэлүүн болдог），右手握着一块髀石大小的血块。这被视为征服者的征兆。他的父亲也速该（ᠶᠢᠰᠦᠭᠡᠢ / Есүхэй）用自己刚刚俘获的一位塔塔儿（ᠲᠠᠲᠠᠷ / Татар）首领的名字给他命名。有人从中看到了伟大的命运；也有人或许看到的是血腥的命运。那时还没有人知道，这个男孩将统一草原，建立历史上最大的陆地帝国。",
  "mongols:death": "1227年，成吉思汗（ᠴᠢᠩᠭᠢᠰ ᠬᠠᠭᠠᠨ / Чингис хаан）在征讨西夏的途中去世。他的遗体被运回蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол），秘密葬在圣山不儿罕·合勒敦（ᠪᠤᠷᠬᠠᠨ ᠬᠠᠯᠳᠤᠨ / Бурхан Халдун）附近。马可·波罗听说，送葬的队伍杀死了途中遇到的每一个人；后来的传说还说，人们驱赶马群踏过墓地，直到它消失不见，上面长出了一片森林。蒙古人通过八白室（鄂尔多斯）来祭奠他，至今仍有人在那里侍奉他的英灵。",
  // ── Jurchens ──
  "jurchens:hunt": "辽朝皇帝珍视海东青，那是女真土地上一种迅捷的白色猎隼。每年辽朝使者都来索要海东青，还要求女真女子陪侍。女真猎人不得不沿着通往海边的“鹰路”与邻近部落作战，才能捕到这种鸟。怨恨一年年加深。为辽廷捕猎天鹅的猎隼，引燃了最终摧毁辽朝的起义。",
  "jurchens:battle": "1115年，刚刚称帝建立金朝的女真首领完颜阿骨打，在护步答冈迎战辽朝天祚帝的庞大军队。金军大约只有两万骑兵；据说辽军多达数十万。阿骨打用刀划破自己的脸，告诉部下，他们必须死战，否则就会被消灭。女真骑兵冲向辽军中军，将其击溃。辽朝从此一蹶不振。",
  "jurchens:gather": "女真的河流出产北珠，取自冰冷的松花江和黑龙江中的河蚌，在辽、宋两朝的宫廷中备受珍视。采珠人在深秋凿开冰面潜水采集，许多人因此丧命。女真人还在森林中采集人参、貂皮和蜂蜜。其中很大一部分作为贡品交给了他们的宗主，等到起兵反抗之时，女真人对每一份贡品都记恨在心。",
  "jurchens:ritual": "12世纪宋朝的一部史书《三朝北盟会编》记载，在女真人中，“珊蛮”是女真语中对女巫的称呼，她们能与神灵相通。这是“萨满”一词最早的文字记载之一。女真萨满击鼓，身佩铃铛和铜镜，向天神、山神和祖先询问疾病、战争和未来。清朝宫廷一直保留这些祭仪，直到1912年。",
  "jurchens:rain": "想象：金朝某个干旱的夏天，满洲的女真村民眼看着黍子在万里无云的天空下枯萎。萨满在院子里立起一根柳木杆，妇女们端来酒和糕饼，鼓声一直响到深夜，她在呼唤天上的神灵。男人们每天清晨出门眺望北方的群山，等待那些能告诉他们神灵已经听见的云。",
  "jurchens:flood": "1194年，在女真人统治的金朝，黄河在阳武决堤，河道南移，汇入淮河水系。平原上大片农田变成沼泽，此后六百多年黄河都没有回归北道。金朝官员竭力重修堤坝，而帝国同时还面临着来自蒙古草原日益增长的威胁。对当地农民来说，仿佛整个世界都挪了位。",
  "jurchens:wind": "想象：女真猎人冬季猎貂归来时，暴风雪在松花江上游的森林中呼啸。他们在雪中挖出藏身之处，紧贴着马和狗，盖着兽皮熬过风暴。一位长老对着北风之神唱起一首古老的歌。大风终于停息后，他们清点人数，发现所有人都还活着，便继续骑马前往炕灶炊烟袅袅的村庄。",
  "jurchens:fire": "1127年，女真金朝的军队在靖康之变中攻陷了宋朝都城开封。他们掳走了退位的徽宗和在位的钦宗、数千名宫廷人员，以及皇家的珍宝和藏书，这座大城的部分地区也被焚毁。对女真人来说，这是起兵后仅仅十来年就取得的惊人胜利；对中原人来说，它成了国耻的代名词。",
  "jurchens:thunder": "1232年，蒙古军队围攻金朝都城开封。女真守军使用了一种新式武器：震天雷，即装满火药的铁壳弹，用铁链从城墙上放下，落到下面挖掘城墙的蒙古士兵中间。史家写道，其声闻百里之外，人和铠甲都被炸得粉碎。两年后金朝灭亡，但那次围城的雷声被人们记住了。",
  "jurchens:birth": "女真人的后裔满洲人讲述过这样的故事：三位天女在布库里山脚下的布勒瑚里湖中沐浴。一只喜鹊把一颗红果衔落在最小的佛库伦身上，她吞下红果后便怀了孕。她的儿子布库里雍顺生来就会说话，后来成为努尔哈赤家族的始祖，这个家族建立了清朝。此后喜鹊一直受到敬重，每当有新的希望诞生，人们便讲起这个故事。",
  "jurchens:death": "宋人记述金朝的《大金国志》描述了古老的女真葬俗：死者不用棺椁下葬，焚烧马匹和财物作为祭品（烧饭），送葬者用刀划破额头，让血和泪一起流下，称为“送血泪”。这是看得见的悲伤，是一个尚武民族所能给予的最隆重的哀荣。随着金朝采纳汉人习俗，这些风俗大多逐渐消失了。",
  // ── Khitans ──
  "khitans:hunt": "辽朝皇帝随季节迁徙朝廷，所居营地称为捺钵。春天在长春州的湖泊边，鼓手们惊起天鹅，皇帝放出海东青捕下第一只。头一只天鹅被献到祖庙，并举行头鹅宴来庆祝，贵族们把它的羽毛插在头发上。对契丹人来说，狩猎就是马背上的国家本身。",
  "khitans:battle": "979年，宋太宗围攻辽朝的南京燕京（今北京）。契丹将领耶律休哥和耶律斜轸率军驰援，在高梁河大败宋军。太宗中箭受伤，乘驴车向南逃走。对契丹人来说，这是一场著名的胜利；燕云十六州仍在他们手中，宋朝始终没能夺回。",
  "khitans:gather": "1112年，辽天祚帝在松花江上设春捺钵，各部首领齐聚参加头鱼宴：鱼是从冰窟窿里叉上来的。酒酣之际，他命令女真首领们跳舞。他们一个接一个地跳了，只有完颜阿骨打站着不动，直直地瞪着他。皇帝想杀了他，却被人劝阻了。三年后，阿骨打建立金朝，灭了辽朝。",
  "khitans:ritual": "契丹人传说，一位骑白马的天神男子和一位驾青牛车的天女在两河交汇处的木叶山相遇，他们的八个儿子成了契丹八部。辽朝皇帝在木叶山举行祭山仪，用白马和青牛祭祀天地和祖先。皇帝向神灵祈求胜利、丰美的牧场和子孙繁盛。",
  "khitans:rain": "遇到旱灾时，辽朝宫廷会举行瑟瑟仪来祈雨。人们把柳枝插在地上，皇帝和贵族骑马驰过，用箭射柳。射不中的人要受罚，给射中的人敬酒。如果三天之内下了雨，官员们便会得到赏赐。这是骑马民族的祈祷：拉开弓，为草原召唤雨水。",
  "khitans:wind": "想象：一场春季沙尘暴从戈壁滚滚而来，笼罩了辽朝的营地。黄风在正午遮暗了天空；朝廷的毡帐剧烈摇晃，畜群纷纷背对狂风。契丹牧民把小羊羔拴在毡房里，用布捂着嘴等待。风暴过后，他们走遍牧场寻找走散的羊，萨满焚烧刺柏来净化营地。",
  "khitans:fire": "想象：在辽朝的冬季营地，一盏灯在夜里翻倒，火势在毡帐间蔓延开来。契丹卫兵用兽皮扑打火焰，把马匹赶到安全处，各家各户则拖出孩子和马鞍。黎明时分，萨满撒下灰烬，向火神祷告。契丹人在炉灶前焚烧食物供奉火神，请求它待在本该待的炉灶里。",
  "khitans:thunder": "想象：在辽朝开阔的草原上，夏季的雷暴来得极快，闪电除了马匹和骑手无处可落。暴风雨逼近时，契丹牧民把畜群赶到低洼处，自己平躺在地上。被雷劈死的马就留在原地，因为它属于上天。事后各家向上天献上一只白羊，感谢它饶过了自己。",
  "khitans:birth": "《辽史》记载，872年耶律阿保机出生前，他的母亲梦见太阳落入怀中。他出生时，帐中充满了奇异的光和香气，身体像三岁的孩子一样，一生下来就会爬。在部族仇杀的年代，他的祖母为他担忧，便把他藏了起来，还用烟灰涂黑他的脸。他长大后统一了契丹各部，于907年建立了辽朝。",
  "khitans:death": "926年阿保机去世时，按照习俗，忠心的随从要为他殉葬。他的遗孀述律平皇后把许多官员送进了陵墓。其中一人赵思温回答说：与先帝最亲近的，莫过于您。她回答说，自己的孩子还小，国家需要她，随后砍下了自己的右手，让它与阿保机同葬。人们称她为断腕皇后。更古老的契丹习俗是把死者置于山中的树上。",
  // ── Chinese: siege … wedding ──
  "chinese-middle:siege": "757年安禄山叛乱期间，张巡和许远以数倍于己的叛军为敌，坚守有城墙的小城睢阳长达十个月。粮食吃尽之后，守军先吃茶叶、纸张和树皮，然后吃在城墙上网到的麻雀和老鼠。能拉开弓的人一天比一天少。城池在援军到来前仅仅三天才陷落，但它屏障了淮河流域的富饶之地，那里的人们在庙宇中纪念张巡达数百年之久。",
  "chinese-middle:triumph": "620年，年轻的秦王李世民在北方大破叛军刘武周，凯旋而归。士兵们在行军途中编了一首歌，叫《秦王破阵乐》，大军入城时，长安的人群齐声唱起这首歌。后来他做了皇帝，把它改编成一场盛大的宫廷乐舞，由一百二十名身披铠甲的舞者表演，鼓声远闻百里。连唐朝宫廷的外国宾客都请求聆听这首乐曲。",
  "chinese:build": "16世纪70年代，将军戚继光用砖重修了北京以北的长城，每隔几百步就有一座空心敌楼。士兵、囚犯和雇来的工匠把砖块背上陡峭的山脊；当地传说，山势陡到要把砖绑在山羊角上，让山羊驮上去。在平坦的地段，人们用沉重的石夯夯打土墙，唱着打夯号子，好让每一下都落在一起：一人领唱，全队应和，泥土又被夯下去一指深。",
  "chinese:voyage": "1405年，郑和率领两百多艘船和约两万七千人，从苏州附近的刘家港起航，前往占城、爪哇、锡兰和古里。在此后二十八年间的另外六次航行中，船队抵达了霍尔木兹和非洲海岸。1431年最后一次出航之前，船员们在福建长乐立下石碑，感谢海神天妃（妈祖）：每当风暴之中她的神灯出现在桅顶，大海便归于平静。",
  "chinese-middle:festival": "1127年宋朝都城开封失陷后，孟元老在《东京梦华录》中记下了他对这座城市的回忆。他回忆说，每逢正月十五元宵节，宫门前便堆起一座灯山，杂技艺人、傀儡戏艺人和说书人在街头表演，皇帝还向人群赐酒。在南方，老人们读着这本书落泪，怀念一座再也见不到的城市。",
  "chinese-middle:games": "蹴鞠，即踢一种塞满羽毛的皮球，从汉朝到明朝一直深受喜爱。宋代有各种球社，有自己的规则，也有著名的球员。相传有个名叫高俅的小吏奉命去端王府办差，正赶上球朝他飞来，他一脚把球踢了回去，姿势优美，端王便把他留了下来。端王后来成了徽宗皇帝，高俅也一路升到统领禁军，全凭那一脚好球。",
  "chinese:drought": "1637年至1641年，在明朝最后一位皇帝治下，北方平原一次又一次地久旱无雨。旱灾之后又来了蝗灾。河南和山东的地方志记载，人们吃草根、树皮，最后吃一种叫观音土的白色黏土，它能填饱肚子，却让人慢慢死去。整村整村的人沿路逃荒，背着孩子和无法播种的种粮。许多熬过来的人此后再也不提这段往事。",
  "chinese:quake": "1556年1月23日黎明前，嘉靖大地震袭击了陕西和山西。在黄土高原，大多数人家住在挖进松软山体的窑洞里，窑洞在他们熟睡时坍塌；死者或达八十三万人，是有记录以来死亡人数最多的地震。幸存的学者秦可大为后人写下忠告：初觉地动，不要急着往外跑，要蹲下等待。他的记述在当地流传了几百年。",
  "chinese-middle:winter": "约809年，诗人白居易写下了《卖炭翁》。一位老人在终南山中烧炭，满面尘灰烟火色。他身上衣正单，却心忧炭贱愿天寒。一夜大雪之后，他天不亮就赶着牛车进了长安，两名宫使却用半匹红绡拉走了他整车的炭。每个世纪的读者都能感受到他冻僵的双手和空空的车子。",
  "chinese:plague": "1910年冬，肺鼠疫在哈尔滨爆发，并随着回家过年的工人沿铁路蔓延。年轻的医生伍连德发现，鼠疫是通过呼吸在人与人之间传播的。他让人们戴上纱布口罩，用铁路车厢设立隔离，并且违背根深蒂固的习俗，获准火化了数千具冻僵的尸体。约有六万人死去，但到了春天，疫情结束了。有的家庭为亲人没有坟墓而哭泣；另一些人则因此得以活下来。",
  "chinese:wedding": "想象：在从黄历上选定的吉日，一个清代村庄听到唢呐和锣声由远及近。新郎家的人抬着花轿去迎接新娘，她头蒙红盖头，前一晚已和母亲唱过了按礼要唱的哭嫁歌。在新郎家，新人一拜天地，二拜高堂，夫妻对拜。当晚朋友们挤进洞房闹洞房，直到蜡烛燃尽。",
  // ── Shang: siege … wedding ──
  "shang:siege": "想象：当鬼方的劫掠者从西方而来，商朝一座边城的人们带着猪和粮罐挤进了夯土城墙之内。城墙厚得可以在顶上赶车。每天夜里，贞人都要灼骨观看裂纹：王会派援兵来吗？会有灾祸吗？粮食越来越少，井水越来越浑，妇女们磨着最后的黍米。第九天，王军的战车出现在平原上。",
  "shang:triumph": "甲骨记载，武丁王的配偶妇好曾率军征讨土方和羌人，有一次兵力约一万三千人，是甲骨所载规模最大的军队。大军归来时，俘虏和战利品在宗庙里献给王室祖先，青铜器中斟满了酒，大鼓擂响。她去世后，武丁为她下葬，随葬有青铜钺、数百件玉器，以及铸有她名字的礼器。",
  "shang:build": "约公元前1600年，商人在郑州筑起城墙：近七公里长的夯土墙，有些地方底部厚达二十米。想象：数千名农民在两季收成之间的旱季劳作。他们立起木板，倒入几指厚的黄土，用捆扎起来的木夯用力夯实，一层又一层，夯声和着号子的节拍。每层约一掌厚；城墙每天长高一点点。",
  "shang:voyage": "《尚书》保存了盘庚王的讲话。约公元前1300年，他把商人迁到今天安阳附近的殷。百姓不愿离开旧城，怨声载道。盘庚斥责他们，又好言劝慰：他说，祖先们以前就迁徙过许多次，新的家园会带来新的生机，就像倒下的树上长出新芽。他们出发了，带着青铜器和粮食，此后直到商朝灭亡，殷一直是都城。",
  "shang:festival": "商朝晚期的君王遵行周祭，即依次向每一位王室祖先献上五种祭祀，按名字逐一祭祀，日期选在十日一旬中与该祖先名号相合的那一天。一个完整的周期约需360天，因此这一仪式本身就在计年。想象：每当新的周期开始，鼓声响起，青铜爵中斟满了酒，以嗜酒闻名的商人一直宴饮到深夜。",
  "shang:games": "想象：在殷都外的原野上，年轻的商朝贵族们为战争和田猎而练习。驭手驾着双马战车在压实的土地上竞驰，辐条车轮嘎嘎作响，驭手在转弯时侧身倾斜，身旁的射手则向靶子放箭。甲骨记载王占问他的战车是否会遇到不测；甲骨上还记有一次田猎时车翻了，一位王子被甩了出去。人群为最大胆的驭手欢呼，王在一旁观看。",
  "shang:drought": "后世的中国人传说，商朝的开国君主成汤即位之后，七年不雨。贞人说必须用人献祭。汤说：若必须用人，就用我吧。他剪下头发和指甲，沐浴斋戒，来到桑林献出自己，把罪责归于自己而非百姓。故事的结尾说，火还没有点燃，大雨便倾盆而下，遍及全境。",
  "shang:quake": "想象：夜里，殷都的大地震动起来。宫殿的夯土墙裂开，屋梁坠落，人们冲进黑暗之中。早晨，贞人灼烧龟甲，向祖先发问：是至上神帝不高兴了吗？是哪位祖先在索要祭品吗？人们杀牛斟酒。百姓们像祖先一样在原来的地基上重建房屋，许多个夜里都在侧耳倾听大地的动静。",
  "shang:winter": "想象：甲骨中有关于雪和寒风的占问，在殷都的一个寒冬里，贞人一次又一次地问雪会不会停。河流封冻，人们清点黍米存粮，各家挤在半地穴式房屋的火塘边。男人们到雪地里猎鹿。王向河神和山神献祭，祈求春天到来，人们则等待着，倾听冰面开裂的声音。",
  "shang:plague": "甲骨中满是疾病的记录：王的牙齿、眼睛、肚子，还有许多问题是在问某种病是否由发怒的祖先降下。有些卜辞问是否会有疾年。想象：一场热病在殷都蔓延，一家又一家的人卧倒在席上。贞人指出了作祟的祖先，王献祭安抚他，人们等待着，想知道裂纹说的是不是实情。",
  "shang:wedding": "想象：商王从许多结盟的氏族中娶妻，甲骨中甚至有占问该娶哪个氏族女子的记录。这一次，一位新娘带着随从、牛和青铜器从方国而来。她被领到殷都的宗庙，贞人已经选定了日子，并把这桩婚事告知了祖先。鼓、青铜铃和陶埙齐奏；美酒流淌；她的到来使她的氏族与王族结为一体。",
  // ── Shu: siege … wedding ──
  "shu:siege": "263年，魏将钟会率大军进攻蜀国。姜维把蜀军撤回剑阁，那是峭壁间的一道裂隙，正如李白后来所写，一夫当关，万夫莫开。他们缺粮坚守了一个秋天，望着下面魏营的篝火。剑阁始终没有失守。但另一支魏军从一条秘密小路翻越群山，成都在他们身后投降了。史书记载，剑阁的士兵们悲愤地在岩石上砍断了自己的刀剑。",
  "shu:triumph": "225年，诸葛亮率蜀军南下进入南中山区。后来的故事说，他七次擒获首领孟获，又七次放了他（七擒七纵），直到孟获发誓永不再反。冬天大军返回成都时，百姓们出城迎接，南方从此安定下来。当地传说还把第一批馒头归功于这次南征：它们被做出来代替用人头祭祀河神。",
  "shu:build": "蜀地位于秦岭之后，它的军队依赖栈道：在陡峭的崖壁上凿孔插入木梁，上面铺设木板，悬在河谷之上。蜀国工匠一次又一次地修补和重建栈道。为了在栈道上运粮，诸葛亮让人造了木车，称为木牛流马。想象：木匠们吊在绳索上，齐声唱着号子，把沉重的木梁荡进孔中。",
  "shu:voyage": "208年，曹操的军队南下，刘备离开樊城。十几万百姓选择跟随他，带着几千车家当，每天只能走几里路。部下劝他丢下百姓赶紧逃走。他拒绝了：他说，成大事者必以人为本；如今人归附于我，我怎么能忍心抛弃他们？在长坂，敌军骑兵追了上来，百姓四散奔逃。但仍有许多人到达了南方。",
  "shu:festival": "想象：在锦官城成都，新年伴着竹子在火中噼啪爆响的声音到来，用来吓走恶鬼。各家在门上挂起桃木符，喝椒酒，先从最小的喝起，因为他们又长了一岁，最后才轮到最年长的人。集市上，织工们展示新织的蜀锦，孩子们拿着四川甘蔗做的糖在摊位之间跑来跑去。",
  "shu:games": "244年，魏军进攻汉中，蜀国大臣费祎准备率军驰援。学者来敏前来送行，请他下一盘围棋。军队已经披甲，战马已经备鞍，费祎却从容对弈，全神贯注。来敏说：我只是在试探您；如此镇定的人，必能破敌。费祎出兵，魏军撤退了。",
  "shu:drought": "想象：都江堰让成都平原保持着葱绿，但在蜀地的丘陵地区，夏雨没有来。梯田龟裂，井水下降。农民们用扁担挑着水桶把水担上山坡，妇女们在李冰祠前祈祷，这位古代的工程师曾驯服了岷江。县令打开了粮仓；百姓们等待着，眼睛盯着西山上空的云。",
  "shu:quake": "想象：蜀地位于全国最不安宁的群山之间。某年春天大地震动，峡谷中整片山坡滑入江中，冲走了一段段通往北方的栈道。村子里木头和泥土造的房屋倒塌了。幸存者在空旷的田野上露宿，不敢再回到屋顶下，士兵们被派出去挖掘。好几个月里，运粮车都无法通行。",
  "shu:winter": "想象：北伐时，蜀军翻越秦岭进入渭河谷地，冬天把他们困在了山中。大雪掩埋了栈道；粮车停了下来；士兵们用稻草和破布裹着脚。从未见过这般严寒的南方农民挤在湿柴生起的火堆旁。大军撤回，诸葛亮写道，国力正在被消耗。士兵们只想再看一眼成都平原。",
  "shu:plague": "在《出师表》中，诸葛亮写道：五月渡泸，深入不毛。南方的河流因瘴气而令人畏惧，那是专门侵袭北方士兵的热病。想象：士兵们只喝煮开的水，嚼着当地向导给的草药，把战友葬在河岸上。回到家乡的人，记得最清楚的是酷热和高烧，而不是战斗。",
  "shu:wedding": "209年，刘备娶了吴主孙权的妹妹，以巩固双方的联盟。史书记载，她性格刚强，喜好武事，身边一百多名侍婢都持刀侍立。刘备每次走进她的房间，心中都不禁凛然。这是两个家族而非两颗心的结合，几年之内她便回到了吴国。",
  // ── Wei: siege … wedding ──
  "wei:siege": "219年秋，关羽围攻樊城，为魏国守城的是曹仁。随后秋雨使汉水泛滥，水位上涨到城墙只露出几尺。部分城墙坍塌，守军与一切援助隔绝。曹仁沉白马于水中，向守军发誓要与他们同生共死，坚守到底。他们在船上和城头作战，一直坚持到援军到来。",
  "wei:triumph": "207年，曹操率军穿越北方荒原，在白狼山击败了乌桓。归途中，在渤海边的碣石，他登上山丘，写下了《观沧海》：日月之行，若出其中。他还写道，神龟虽寿，犹有竟时，而老骥伏枥，志在千里。士兵们一路唱着他的诗回家。",
  "wei:build": "210年，曹操在邺城建造了铜雀台，那是一座建在夯土台基上的高大殿宇，顶上立着一只巨大的铜雀。建成之后，他带着儿子们登台，让他们作赋。年轻的曹植写得又快又好，令父亲大为惊叹。此后几百年间，诗人们不断吟咏这座高台，以及曹操遗命每月在台上为他表演的歌伎。",
  "wei:voyage": "225年冬，魏文帝曹丕率领一支庞大的船队沿运河南下，来到广陵，隔着长江眺望吴国。江水高涨汹涌，对岸排列着城墙和瞭望楼。他望着波涛叹息道：这是上天用来分隔南北的江啊。他身后的水道开始结冰，船队便掉头返回。士兵们很高兴不用渡江就能回家。",
  "wei:festival": "在邺城的魏国宫廷里，建安七子与曹丕、曹植在西园举行春宴。三月上巳节，人们到河边洗去冬天的病气，诗人们则让酒杯在溪水上漂流；酒杯停在谁面前，谁就要喝酒作诗。曹丕后来满怀怀念地回忆起那些日子：宴饮、音乐，以及月光下的朋友们。",
  "wei:games": "曹丕在自己的著作《典论》中写道，他喜爱剑术。一次宴会上，将军邓展夸耀自己的本领，曹丕便以甘蔗为剑向他挑战。他三次击中邓展的手臂，邓展要求再比一回，曹丕又正中他的额头。满堂哄然大笑。曹丕还自豪地写到自己擅长弹棋，那是一种在棋盘上弹射棋子的游戏。",
  "wei:drought": "194年，曹操和吕布正在争夺兖州，旱灾和蝗灾袭来。史书记载，一斛谷价值五十万钱，人相食。双方军队都断了粮，只好罢兵。曹操的士兵们懂得了饥荒的滋味；不久之后，他推行屯田，让士兵和流民耕种荒地，好让军队再也不会那样挨饿。",
  "wei:quake": "想象：魏国某年春天，洛阳大地震动。宫殿屋顶的瓦片纷纷坠落，在重建的城市坊里中，土坯墙裂开了缝。官员们匆匆上奏：学者们说，地震表明阴阳失和，皇帝必须反省自己的作为。普通百姓只是扫起碎瓦，用木头撑住墙壁，在外面睡上几夜。",
  "wei:winter": "206年初，曹操在冬季率军北越太行山平定叛乱，写下了《苦寒行》。诗中说：北风声正悲，雪落何霏霏，熊罴对我蹲，虎豹夹路啼。士兵们没有粮食，没有住处，没有柴火；他们斧冰持作糜。连将军也思念故乡。士兵们从他的诗句中认出了自己的行军。",
  "wei:plague": "217年，一场可怕的瘟疫席卷中国北方。曹植写道：家家有僵尸之痛，室室有号泣之哀。建安七子中有四人在同一年死去。曹丕在给朋友吴质的信中写道：去年疾疫，亲故多离其灾。想到我们曾一起骑马、饮酒、作诗，如今他们都化为尘土，我的悲伤无法用言语表达。",
  "wei:wedding": "204年，曹操的军队攻下邺城，年轻的曹丕走进了袁家的宅院。据说他在那里发现了甄氏，她把脸埋在婆婆的膝上。他抬起她的脸，被她的美貌所打动，不久便娶了她。她以优雅和学识闻名，后来成了未来的皇帝曹叡的母亲。后世的诗人还想象曹植也曾爱慕过她。",
  // ── Wu: siege … wedding ──
  "wu:siege": "222年至223年，曹真率领的魏军包围了江陵，为吴国守城的朱然只有约五千人。敌军堆起土山、立起高楼，箭如雨下射进城中，还架起浮桥通往江心洲。随后城内疾病蔓延，能作战的守军不到一半。朱然镇定自若，鼓舞士气，还查出并处决了一名内奸。六个月后，魏军放弃围攻，撤军回家。",
  "wu:triumph": "208年赤壁之火过后，三十四岁的周瑜作为英雄凯旋。他精通音乐：吴国人说，乐师即使在他喝了三杯酒之后弹错一个音，周郎也会回头看（曲有误，周郎顾）。想象：在庆功宴上，歌者们故意弹错几个音，只为让这位英俊的年轻将军朝她们看一眼。整个吴国宫廷都笑了，士兵们举杯向救了他们的那阵风致敬。",
  "wu:build": "212年，孙权把长江边山上的旧堡垒改建成石头城，守卫他的新都建业。工匠们沿着江水贴近的崖壁切割、垒砌红色砂岩。想象：船夫们摆渡运送石块，劳工们和着号子的节拍用绳索把石块拉上去，领头的人一喊，众人齐声应和。吴国水军的战船就停泊在城墙之下。",
  "wu:voyage": "230年，孙权派将军卫温和诸葛直率一万士兵渡海，寻找名叫夷洲和亶洲的岛屿。他们向东驶入茫茫大海，可能到达了台湾。一年之后，疾病已夺去了十之八九的士兵。他们带着几千名岛民回来，朝廷却惩处了两位将军。这是有记载的最早从大陆横渡那道海峡的航行之一。",
  "wu:festival": "在吴国所在的江南，五月初五的端午节是为纪念一位本地英雄而过的：伍子胥。几百年前他的尸体被抛入江中，据说他化为神灵，驾着潮水而来。想象：村民们在鼓声中划着彩绘的长船竞渡，把用叶子包着的米投入水中，并在门上挂起艾草，抵御夏天的毒气和疾病。",
  "wu:games": "吴国人喜爱围棋。有一份古老的棋谱据说来自孙策与部将吕范的对局，不过史家对此存疑。建业的文士们在灯下彻夜对弈，吴国作家韦昭甚至写了一篇文章反对下棋，抱怨年轻人把时光都浪费在了上面。想象：营中的士兵在地上划出棋盘，用小石子对弈。",
  "wu:drought": "想象：长江下游的一个旱年，吴国的稻田龟裂，运河干成了烂泥。农民们日夜踩着木制的龙骨车，唱着歌让脚步合拍，把剩下的一点水提上来。妇女们向江神和龙王烧香。建业的粮仓打开了，船只从上游运来稻米。雨终于来时，孩子们跑出去在雨中跳舞。",
  "wu:quake": "想象：某个夏夜，吴国都城建业的大地震动起来。殿中的钟自己响了起来，屋瓦滑落，集市巷子里的木屋摇摇晃晃，有些倒塌了。人们在黑暗中逃往江边，向神灵呼喊。早晨，官员们清点损失，卜者们争论这意味着什么。船夫们说是江水跳了起来，老人们则到土地庙去祈祷。",
  "wu:winter": "224年冬，魏文帝曹丕率领庞大的船队来到长江北岸。吴将徐盛让部下连夜沿南岸用木头和芦苇搭起绵延数百里的假城墙和假楼。曹丕看到的似乎是一座无边无际的要塞，而江面风急浪高、寒冰刺骨。魏国船队掉头而去。在芦苇墙后的岸边冻得发抖的吴国士兵们，如释重负地笑了。",
  "wu:plague": "想象：在南方河流沿岸的吴国驻军中，潮湿的夏天里热病穿过营房。北方出生的士兵最先倒下，然后是本地人。军医们在大锅里煮草药，病人一排排躺在屋檐下，由战友们为他们扇风。每天都有更多的人被抬到山上。军官们写信给建业请求补充兵员。康复的人回到岗位上，消瘦而沉默。",
  "wu:wedding": "约199年，孙策和他的好友周瑜攻下皖城，在那里娶了两位以美貌闻名的姐妹，大乔和小乔。孙策对周瑜开玩笑说，虽然战乱不断，能娶到乔家姐妹为妻也就足够快乐了。后来的诗人们喜爱这对婚礼：两位年轻的英雄，结义的好友，如今又成了连襟。不到一年，孙策就死了。",
  // ── Zhu Xi's Legacy: siege … wedding ──
  "zhu-xis-legacy:siege": "从1243年起，四川合川的宋朝军民坚守钓鱼城，这是一座位于三江之间、筑有城墙的山顶台地。难民们在城内耕种田地，从城中的井里汲水，因此能够坚持多年。1259年，蒙古大汗蒙哥亲自围攻钓鱼城，死于城下。钓鱼城前后共坚守了约三十六年。1279年它终于打开城门时，也是以城中百姓得以保全为条件的。",
  "zhu-xis-legacy:triumph": "1161年，金军抵达长江边的采石。那里的宋军没有统帅，士兵们绝望地坐在路边。虞允文是一名文官，本来只是奉命来犒劳军队的，他却召集起士兵，亲自指挥江上船队。车船击退了金军。采石大捷的消息传到江南，百姓们欢欣鼓舞；一位书生救了他们，道学家们把他视为书生之勇的证明。",
  "zhu-xis-legacy:build": "1179年，南康知军朱熹发现庐山脚下古老的白鹿洞书院已经荒废。他用自己的俸禄和朋友们的捐赠重建了书院，收集书籍，并写下了院规：父子有亲，君臣有义。想象：石匠和木匠们在松树下劳作，学生们在课间搬运瓦片，一边爬山路一边背诵经书。",
  "zhu-xis-legacy:voyage": "1167年，朱熹从福建跋涉一千多里来到长沙，到岳麓书院拜访他的朋友张栻。两人辩论心性问题长达两个月，有时三天三夜不眠不休。学生们蜂拥而来听讲；当地传说，骑马来的人多得让马把池塘的水都喝干了。之后，两人一同冒雪登上衡山，一路作诗。",
  "zhu-xis-legacy:festival": "朱熹在《家礼》中规定了一个家庭应当如何迎接新年。正月初一天亮之前，家长打开祠堂，点香，向祖先牌位献上酒和茶。然后全家按长幼次序向长辈行礼。想象：礼毕之后，福建一个小镇的巷子里响起鞭炮声，孩子们穿着新衣跑出去给叔伯们拜年。",
  "zhu-xis-legacy:games": "儒家保留着一种古老的乡里射箭仪式，即乡射礼，朱熹的门人复兴了它。想象：在福建一座书院的庭院里，两对射手上前，行礼，在琴瑟和鼓乐声中轮流放箭。重要的不只是射中靶子，还要合乎节拍、保持镇定、向胜者行礼。输的人笑着罚饮一杯酒，大家都认为这一礼仪让他们成了更好的人。",
  "zhu-xis-legacy:drought": "1181年，浙东遭受旱灾和饥荒，朝廷派朱熹主持赈灾。他一个村一个村地走访，常常步行，检查粮仓，核实粮食是否真正到了饥民手中而不是落入胥吏的口袋。他上奏朝廷，描述了一家家人吃草、卖儿鬻女的惨状。他认为，读书人的学问如果不能填满饥饿之人的饭碗，就毫无意义；那个冬天他操劳得精疲力竭。",
  "zhu-xis-legacy:quake": "想象：一天夜里，在福建的一个山谷中，大地轰鸣，一座书院的讲堂摇晃起来，书卷和砚台掉落一地。学生们冲进庭院。早晨，他们的老师，一位朱熹的门人，把他们召集到碎瓦之间，讲起了“敬”：天地震动之时，君子反躬自省，保持心境安定。然后他们挽起袖子，帮助村民们重建家园。",
  "zhu-xis-legacy:winter": "1093年，学者杨时和游酢去拜访他们的老师程颐，程颐的学问后来由朱熹继承。他们发现老师正闭目静坐，不敢惊醒他，便站在门外等候。等程颐终于睁开眼睛时，门外的雪已经积了一尺深。这个“程门立雪”的故事，成了学生尊师重道的典范。",
  "zhu-xis-legacy:plague": "想象：一场瘟疫席卷福建某县时，当地信奉朱熹学说的士人们在书院讲堂里聚会。他们打开社仓救济病人，自掏腰包购买草药，并把药方写成告示贴在路口。有些人家逃走了；士人们留了下来，说邻里受苦之时正是体现仁的时候。他们按照礼仪安葬死者，好让生者的礼仪即使在灾难中也不致中断。",
  "zhu-xis-legacy:wedding": "朱熹的《家礼》规定了一套简化的婚礼，流传于中国、朝鲜和越南。新郎亲自骑马去迎娶新娘（亲迎），献上一只大雁以示忠贞，并向她的父母行礼。在新郎家，新人相互行礼，用剖成两半、以红绳相连的葫芦饮酒（合卺）：两人合为一体。想象：迎亲队伍离开时，新娘的母亲在门口落泪。",
  // ── Japanese: siege … wedding ──
  "japanese:siege": "1333年，楠木正成率领约一千人据守金刚山上的小山城千早城，对抗庞大的镰仓幕府军。《太平记》记载，守军向攀爬的敌人滚下圆木和巨石，泼下沸水和燃烧的油，还给稻草人穿上铠甲，引诱敌人暴露在开阔处。围攻者试图切断水源，城中却有自己的泉水。千早城坚守了数月，这场围城比镰仓幕府本身存在得还要久。",
  "japanese:triumph": "1274年，蒙古船队在博多登陆时，肥后的年轻武士竹崎季长冲在前面，抢夺头功。入侵者撤退后，他等着封赏，却什么也没等到。于是他一路骑马来到镰仓，亲自陈情，终于获得了领地和一匹马。为表感激，他让人把自己的事迹画成绘卷，即《蒙古袭来绘词》，画中的他至今仍在箭雨和爆炸的铁炮中策马疾驰。",
  "japanese:build": "743年，圣武天皇发愿在奈良东大寺铸造一尊巨大的铜佛，并希望每个人哪怕只献上一根草、一把土。深受百姓爱戴的僧人行基从全国各地募集了工匠和捐献。据说有约二百六十万人参与其中。752年开眼供养法会上，一位印度僧人为大佛点上眼睛，来自远至唐朝和朝鲜的乐师们演奏了雅乐。",
  "japanese-early:voyage": "804年，年轻的僧人空海随遣唐使船队前往唐朝。一场风暴吹散了四艘船；他的船漂流了一个多月，在遥远南方的福建靠岸，官员们把这群衣衫褴褛的旅人当成了海盗。空海用典雅的汉文写了一封信，令长官大为惊叹，放他们前往长安。四艘船中有两艘失踪了。他带着真言宗的密教教法回到了日本。",
  "japanese:festival": "想象：岁末，在江户的一户町家里，邻居们聚在一起捣年糕，一人抡起沉重的木槌，另一人在两槌之间翻动热气腾腾的米团，口中有节奏地喊着号子。门口立着松竹做的门松。午夜，寺院的钟敲响108下，驱除108种烦恼。元旦早晨，一家人喝杂煮汤，孩子们领到压岁钱，大家一起出门去做新年的首次参拜。",
  "japanese:games": "18世纪80年代和90年代，江户人为相扑而疯狂。伟大的力士谷风梶之助连胜63场，1789年，他和小野川成为最早被授予横纲白绳的人。人群挤满了寺院举办劝进相扑的场地，力士的浮世绘到处都在卖，每天早晨，高高的鼓楼上的鼓声召唤全城去看比赛。谷风于1795年死于一场瘟疫，至死仍是冠军。",
  "japanese-early:drought": "1181年，干旱以及随之而来的养和饥荒袭击了都城京都。鸭长明在《方丈记》中写道，饥民倒毙在墙边和河岸，死尸的气味弥漫全城。一位名叫隆晓的僧人走遍街巷，在死者的额头上写下梵文的“阿”字，让他们与佛结缘；长明写道，两个月里，他单在城中就数了四万二千三百多具。",
  "japanese:quake": "1855年11月11日夜，安政大地震袭击了江户。地势低洼的商人街区四处起火，数千人死亡。几天之内，一种叫“鲶绘”的浮世绘就充斥了全城：画的是在地下翻腾、引起地震的巨大鲶鱼，被愤怒的市民痛打，或被鹿岛之神压住。有些画还描绘木匠和泥瓦匠因为有了重建的活计而向鲶鱼道谢。人们笑着看这些画，借以承受悲伤。",
  "japanese:winter": "1837年，越后的布商铃木牧之出版了《北越雪谱》。他想让城里人了解雪积得比房子还高的地方是怎样生活的。他写道，冬天里，人们从门口挖出隧道，在积雪压垮屋顶之前把雪铲下来，穿着雪鞋走路。雪崩会掩埋旅人；妇女们在漫长幽暗的月份里织出著名的越后缩布，到了春天再把它铺在雪上漂白。",
  "japanese:plague": "735年至737年，天花从九州席卷全日本。也许有四分之一到三分之一的人死去。在都城奈良，朝中权势最大的藤原四兄弟在一年之内全部死去。农民们抛弃了田地，朝廷向各地运送稻米和药物。悲痛和恐惧之中，圣武天皇皈依了佛陀；他下令在各国建造寺院，随后又建造了东大寺的大佛。",
  "japanese-early:wedding": "在平安时代的贵族中，婚姻始于年轻男子的秘密来访。他夜里来到女子家中，天亮前离开，然后送上一首后朝之歌。如果他连续三夜都来，婚事便定了下来：第三夜，女方家人为新人端上小小的年糕，即三日夜饼，次日再设宴，把他介绍给女方家人。那个时代的文学里，满是和歌与离别时的衣袖。",
  // ── Yamato: siege … wedding ──
  "yamato:siege": "587年，反对新传入的佛教的权臣物部守屋，用稻秆栅栏加固了他在涩川的宅邸，抵抗苏我氏的进攻。他的弓箭手从树上放箭，进攻者三次败退。十四岁的厩户皇子，即后来的圣德太子，雕刻了四天王像，发誓若能获胜便为他们建造寺院。守屋被射落树下，据点陷落，四天王寺随后在难波建成。",
  "yamato:triumph": "想象：在大型古坟的时代，武士们从西方的征战中返回大和盆地的村庄。他们戴着铁盔，穿着铁片缀成的短甲，就像立在坟丘上的埴轮武士一样。妇女们跑出来迎接他们；巫女摇动挂着铃铛的铜镜；长老们捣米准备宴席。男人们围着篝火讲述渡海的经历，鼓手和歌者把他们的事迹编成了歌。",
  "yamato:build": "《日本书纪》记载，仁德天皇登上高台，看到百姓家中没有炊烟升起，便免除了三年的全部赋税，尽管他自己宫殿的屋顶都在漏雨。等炊烟重新升起，百姓们欣然前来为他修建宫殿。以他命名的大型锁孔形坟丘，即堺市附近的大仙古坟，长近半公里。想象：数千名劳工背着一筐筐泥土，唱着歌保持步调，护城壕渐渐注满了水。",
  "yamato:voyage": "607年，小野妹子从难波起航前往中国隋朝宫廷，带着一封开头写着“日出处天子致书日没处天子”的国书。隋炀帝很不高兴，但还是派了一名使者随他回国。航程十分危险；船只沿朝鲜半岛海岸航行，等待合适的风向。此后的使者和留学生们带回了佛教、文字和律令。",
  "yamato:festival": "在十一月的新尝祭上，大和的统治者把当年的新米献给众神，并与众神一同食用，以此更新上天与稻田之间的纽带。古老的地方志记载，在乡村里，青年男女登上筑波等山参加歌垣，那是一种整夜互相对唱、以歌传情的节日。",
  "yamato:games": "《日本书纪》记载，垂仁天皇在位时，一个名叫当麻蹶速的大力士夸口说，全国没有人能比得上他。天皇从出云召来了野见宿祢，两人在天皇面前互相踢击搏斗，最后宿祢踢断了蹶速的肋骨和腰骨。这被视为相扑的起源。宿祢后来还建议用陶土埴轮代替王陵中的人殉。",
  "yamato:drought": "《日本书纪》记载，642年夏天干旱持续了很久。村里的祝部按照古老的习俗杀马杀牛献祭，迁移集市；随后大臣苏我虾夷让寺院诵读佛经，却只下了一点小雨。最后，皇极天皇来到南渊的河源，跪下向四方礼拜，仰望上天。记载说，雷声响起，大雨下了五天。",
  "yamato:quake": "《日本书纪》记载，684年，一场大地震撼动了全国，这是有记录的最早的南海地震。男女老少呼喊着四散奔逃；山崩河涌。寺院、神社和仓库都被摧毁。在土佐，五十多万代的田地沉入海中。伊豆的老人们说他们从未见过这样的事，海啸袭击了海岸。",
  "yamato:winter": "想象：大和盆地的一个严冬，山丘上积雪很深，储存的稻米日渐短缺。各家挤在竖穴住居的火塘边，烧着柴草，裹着麻布和毛皮。男人们进山猎鹿和野猪；妇女们在雪下挖掘根茎。冬至时，巫师举行仪式召唤太阳回来，长老们唱着古老的歌，一直唱到春天到来。",
  "yamato:plague": "《日本书纪》记载，崇神天皇在位时，一场大瘟疫夺去了一半以上百姓的生命，还有许多人背井离乡。天皇斋戒祈祷。在梦中，三轮山的大物主神现身，说这场疾病是他所为，只要让一个名叫大田田根子的人做他的祭司，天下就会太平。人们找到了大田田根子，祭祀了大物主神，瘟疫便结束了。",
  "yamato:wedding": "《古事记》讲述了伊邪那岐和伊邪那美两位神如何缔结第一桩婚姻。他们从相反的方向绕着天之御柱行走，然后相遇。伊邪那美先开口说：多么好的少年啊！但这次结合生下的孩子是失败的，因为女方先开了口。他们又绕了一次；这一次伊邪那岐先开口，从这桩婚姻中诞生了日本列岛。大和人把它讲述为一切婚礼的范本。",
  // ── Sengoku Daimyo: siege … wedding ──
  "sengoku-daimyo:siege": "1575年，武田胜赖率一万五千人围攻长篠城；城内只有约五百人，粮食几乎耗尽。足轻鸟居强右卫门趁夜溜出城，游过河去，找到了德川家康，家康答应派兵救援。他在返回途中被俘。武田军让他向城里喊话，说援军不会来了。他却高喊：援军就快到了，坚持住！他在城墙下被杀，长篠城守住了。",
  "sengoku-daimyo:triumph": "1560年，只有几千人马的年轻领主织田信长，在桶狭间的一场突如其来的暴雨中突袭了今川义元的大军，义元被杀。出征之前，信长唱起并舞了一段幸若舞《敦盛》：人间五十年，如梦亦如幻。胜利之后，他到热田神宫谢神，并在那里修建了一道带屋顶的土墙，至今仍被称为信长塀。尾张的百姓们为这位以少胜多的领主欢庆。",
  "sengoku-daimyo:build": "从1576年起，织田信长在琵琶湖畔的山丘上修建安土城，城中有一座涂金髹漆的七层天守。一块名叫蛇石的巨石，由约一万人用三天时间拖上山去。据太田牛一的记载，他们在笛声、鼓声和歌声中拖拉，好让绳索齐心用力。巨石曾滑落一次，压死了一百多人。",
  "sengoku-daimyo:voyage": "1582年，四名日本少年，九州的基督教学生，从长崎启程前往欧洲：这就是天正遣欧使节。他们经澳门、果阿，绕过非洲，1584年到达里斯本，1585年到达罗马，教皇接见了他们，人群对他们的和服惊叹不已。他们学会了弹奏羽管键琴、鲁特琴和竖琴。1590年回国后，他们为丰臣秀吉演奏西洋音乐，秀吉要求听了三遍。",
  "sengoku-daimyo:festival": "1598年春，丰臣秀吉在京都醍醐寺举办了盛大的赏樱会（醍醐の花見）。他命人种下七百株樱树，约一千三百位宾客，大多是他家中的女眷，穿着新做的和服前来，一天之中还换了两次衣服。小路两旁设有茶屋，枝头系着诗笺，花下奏着音乐。秀吉年老多病；那年夏天他去世了，这场花会成了他的告别。",
  "sengoku-daimyo:games": "织田信长喜爱相扑。据太田牛一记载，1578年，他在安土城召集了各国的一千五百名力士，从早到晚观看他们比赛。获胜者得到了刀剑、白银，甚至被收为家臣。信长的奉行们划出场地并裁判比赛，有人说这有助于形成后来相扑的圆形土俵。人群的欢呼声在城山上回荡。",
  "sengoku-daimyo:drought": "想象：战国时代的一个干旱夏天，近江一个村子的灌溉池塘干成了龟裂的泥地。上游和下游的村子以前就为争水打过架，有时甚至动了长枪。这一次，长老们在神社里聚会，约定以燃香计时来分水（番水）：每个村子在一支香燃尽的时间里打开水闸。然后他们跳起祈雨舞，整夜击鼓。",
  "sengoku-daimyo:quake": "1586年1月，天正大地震撼动了日本中部。正在琵琶湖畔坂本的丰臣秀吉丢下一切，逃往大坂。在飞驒的山中，一场山崩掩埋了归云城及其下的城下町；为庆祝和议而聚集在一起的内岛氏一族，一夜之间全部消失。关于他们被埋的黄金的传说至今仍在流传。在若狭湾沿岸，海啸卷走了渔村。",
  "sengoku-daimyo:winter": "1584年冬，武将佐佐成政冒着深雪翻越北阿尔卑斯山，经由立山连峰的佐良峠，去滨松投奔德川家康。这是一次孤注一掷的跋涉；据说他的许多部下都被冻死了。结果家康已经议和，这次翻越成了徒劳。这个被称为“さらさら越”的故事，在富山被当作一个面对群山不屈不挠的勇气故事流传下来。",
  "sengoku-daimyo:plague": "战国时代天花一次又一次地流行。约1572年，它袭击了一个孩子，伊达家的继承人伊达梵天丸；高烧夺去了他右眼的视力。据说他的母亲从此对这个毁了容的儿子冷淡起来。他长大后成了仙台藩主伊达政宗，人称独眼龙。各地的人家都挂起红色护符，画上武将为朝的红色画像，用来吓走痘神。",
  "sengoku-daimyo:wedding": "约1561年，一个名叫藤吉郎的贫穷足轻，也就是后来的丰臣秀吉，不顾女方母亲的反对，娶了武士家的女儿宁宁（ねね）。宁宁后来回忆说，婚礼是在他狭小的长屋里举行的，泥土地上铺着草席，只有最简单的饭菜和清酒。他们这桩出于爱情的婚姻，一直延续到他登上天下之主的地位。她始终是他最亲密的伴侣和谋士，他每次出征都给她写充满爱意的信。",
  // ── Koreans: siege … wedding ──
  "koreans:siege": "1636年冬，清军长驱南下，仁祖（인조）和朝廷逃进了山城南汉山城（남한산성）。约一万三千名守军在严寒中坚守城墙四十七天。粮食渐渐短缺；士兵们的手冻在了兵器上；战马被宰杀充饥。城内，大臣们在坚守与议和之间激烈争论。最后，国王走下山城，到三田渡（삼전도）投降，士兵们看着这一幕痛哭流涕。",
  "koreans-early:triumph": "1019年，高丽（고려）将军姜邯赞（강감찬）在龟州（귀주）歼灭了一支契丹军队；史书说十万人中只有几千人逃脱。这位年过七旬的老将带着军队凯旋时，显宗（현종）亲自出城迎接，亲手在他头上插了八朵金花。开京（개경）的百姓们夹道欢呼，迎接这位救了他们的身材矮小、相貌平平的文臣将军。",
  "koreans:build": "1794年至1796年，正祖（정조）在水原（수원）修建了华城（화성）。学者丁若镛（정약용）设计了一种带滑轮的起重装置，名叫举重机（거중기），让几个人就能吊起沉重的石块。在当时不同寻常的是，劳工们都领取工钱，夏天酷热时，国王还给他们送药。每个工人的名字和工钱都记录在《华城城役仪轨》（화성성역의궤）中，并附有每件工具的图样。",
  "koreans:voyage": "1488年，文官崔溥（최부）从济州（제주）乘船回乡为父亲奔丧，一场风暴把他的船吹到了海上。四十三个人漂流了十四天，淡水耗尽，喝雨水，甚至喝自己的尿。他们漂到了浙江海岸，被当成海盗，后来又被护送一路到北京，再经陆路回国。所有人都活了下来。崔溥把这一切写成了《漂海录》（표해록）。",
  "koreans:festival": "八月的丰收满月中秋（추석），家家户户回乡拜祭祖坟，清除坟丘上的杂草，献上新米和用松针蒸的松饼（송편）。那天夜里，在南部海岸，妇女们在月光下手拉手围成一个大圈，跳起强羌水越来（강강술래）：一个人唱一句，众人齐声应和，越跳越快，直到天明。",
  "koreans:games": "端午（단오），即五月初五，村民们围在沙地场子边观看摔跤（씨름），两个男人互相抓住对方的腿带。奖品是一头公牛。约1780年，画家金弘道（김홍도）画了一幅摔跤图：两名力士扭在一起，观众围坐四周，摘下帽子，探身向前，还有一个卖麦芽糖（엿）的少年连头都没抬。与此同时，姑娘们穿着最好的衣服，把秋千（그네）荡得高高的。",
  "koreans:drought": "1670年和1671年，旱灾、寒冷和洪水使朝鲜（조선）全境的收成一季接一季地毁掉：这就是庚辛大饥荒（경신대기근）。随后又有蝗灾和瘟疫。死者或达百万人。朝廷削减了自己的膳食，打开粮仓，官员们设立粥厂，饥民成千上万地排队。记载中有母亲把孩子遗弃在路边。后来，老人们从那场饥荒算起自己的一生，称那一年为人人挨饿之年。",
  "koreans-early:quake": "《三国史记》（삼국사기）记载，779年，一场大地震袭击了新罗（신라）都城庆州（경주）。房屋倒塌，一百多人死亡。寺院、宫殿和这座黄金之城的街巷都出现了裂缝。各大寺院的僧人诵经以平息大地，国王打开了粮仓。庆州人用石头和木材重建家园，这件事在史书中留存了一千年。",
  "koreans:winter": "每年冬天来临时，朝鲜每个村子的妇女都会聚在一起腌越冬泡菜（김장），做出足够吃到春天的泡菜（김치）。她们把数百棵白菜用盐腌好，抹上辣椒、大蒜和鱼酱，装进埋在院子里的大陶缸（옹기）中，以免冻住。邻居们一家接一家地帮忙，分享食物，聊着家长里短。屋里，温突（온돌）地板由厨房的灶火加热，一家人挨着睡在温暖的石板上。",
  "koreans:plague": "1821年，霍乱第一次传入朝鲜（조선），从平壤（평양）进入。这种病伴随着让双腿扭曲的痉挛，人们说是一个鼠精在身体里往上爬，于是称之为鼠病（쥐통）。各家在门上贴猫的画像，还用猫皮擦拭病人。几周之内，死者便以万计。国王下令祭祀土地神灵，并打开了药局。",
  "koreans:wedding": "在朝鲜（조선）的婚礼上，新郎骑马来到新娘家，向她的母亲献上一只木雁（기러기），以示要像终生相守的大雁一样忠贞。在院子里，脸颊上点着红点（연지곤지）的新娘向他行礼，他也回礼，两人之间隔着一张摆满栗子、大枣、一只公鸡和一只母鸡的桌子。他们用一只葫芦剖成的两半分饮喜酒。随后新郎的朋友们会打他的脚底来取乐。",
  // ── Choson (Gojoseon): siege … wedding ──
  "choson:siege": "公元前109年，两支汉军包围了卫满朝鲜（위만조선）有城墙的都城王险城（왕검성）。城池坚守了将近一年。想象：城墙之内，粮窖渐渐空了，人们吃马、煮皮革充饥，城头的士兵望着敌人的营寨。大臣们争论是否该投降。公元前108年，其中一些人杀死了右渠王（우거왕），可大臣成己（성기）仍然坚持抵抗，直到他也被杀。随后城门打开了。",
  "choson:triumph": "想象：在古朝鲜（고조선）的青铜时代，武士们从河谷中的一场战斗归来，带回了缴获的马匹和青铜器。村民们跑到支石墓群那里迎接他们。佩戴铜镜和铃铛的巫师跳舞答谢上天，年轻人的脸上涂了彩，人们喝着黍酒，伴着鼓声唱了一整夜。阵亡的人被葬在石下，他们的名字也被唱进了歌里。",
  "choson:build": "想象：在古朝鲜（고조선）的一个作坊里，青铜匠人铸造着标志其疆域的琵琶形铜剑（비파형 동검）。他们在软石上刻出范模，在用风箱鼓风的炭火上熔化铜和锡，一边向火神吟唱，一边浇注发光的金属。外面，村民们筑起一道新的土墙，和着劳动号子用夯捶打泥土。铸好的短剑被交给首领祝福。",
  "choson:voyage": "据中国史书记载，约公元前195年，一个名叫卫满（위만）的人带着约一千名追随者，从动荡的燕地向东逃亡。为了表明自己是和平而来，他梳起椎髻，穿上当地的服装。他渡过浿水（패수），古朝鲜（고조선）的准王（준왕）把边境上的土地给了他，让他守卫。想象：难民们带着孩子蹚过河水，寻找新家园的山丘。",
  "choson:festival": "想象：五月播种结束后，古朝鲜（고조선）一个村子的人们聚在一起祭祀上天。后来的中国作者描述过他们邻近民族的这类节日：人们昼夜饮酒歌舞，数十人排成一行相随，踏地为节，手随之起落。这里也一样，鼓声让他们一直跳到星星隐去，人们还为始祖檀君（단군）留下了祭品。",
  "choson:games": "想象：秋收之后，在古朝鲜（고조선）一座城镇下方的河岸上，年轻人聚在一起比赛。他们射挂在杆子上的靶子，沿着沙滩赛马，在村民围成的圈子里摔跤。最好的射手从首领那里赢得一把青铜刀和一坛酒。老人们把这些年轻人与自己年轻时的英雄相比，姑娘们看见吹牛的人在泥里滑倒，都笑了起来。",
  "choson:drought": "想象：古朝鲜（고조선）的稻田和黍田上没有下雨。天空日复一日地发白。井水下降，河流缩成一个个水洼，长老们领着人们登上圣山。他们在那里向天神献上一头猪和黍酒，鼓擂得震天响，好让云听见。孩子们用陶罐从最后几处泉眼里提水，各家饿着肚子等待着，望着西方。",
  "choson:quake": "想象：一天夜里，古朝鲜（고조선）的山丘震动起来。半地穴房屋坍塌，屋梁掉进火塘，到了早晨，一道裂缝横贯田野。巫师说是地神发怒了，便摇着铜镜和铃铛跳舞来安抚它。村民们把邻居从倒塌的房屋中挖出来，在原来的火塘上重建房屋。此后很长一段时间，孩子们都被叮嘱要睡在门边。",
  "choson:winter": "想象：古朝鲜（고조선）北部的冬天漫长而严酷。河流冻得结结实实，积雪掩埋了村与村之间的小路。各家把房屋半埋在地下，火塘里的火日夜不熄，靠干黍米、橡子和熏肉过活。猎人们踏雪去猎鹿。长老们讲起那只熊的故事：它在黑暗的洞穴里熬过一百天，变成了一个女人。",
  "choson:plague": "想象：一种疾病随着商人沿河而上，来到古朝鲜（고조선）的一个村子，一个又一个人发起高烧。巫师摇着铃铛和铜镜跳了一整夜，祈求神灵把疾病带走。病人被安置在单独的房子里，家人把食物放在门口。疫病过去后，死者被葬在石下，村民们聚集在支石墓旁感恩。",
  "choson:wedding": "《三国遗事》（삼국유사）讲述了古朝鲜（고조선）的建国故事。天帝之子桓雄（환웅）降临太白山（태백산）。一只熊和一只老虎请求变成人；他给了它们艾草和大蒜，让它们一百天不见阳光。老虎放弃了，熊却变成了一个女人，名叫熊女（웅녀）。她在檀树下祈求孩子。桓雄娶了她，他们的儿子就是始祖檀君（단군）。",
  // ── Mongols: siege … wedding ──
  "mongols:siege": "1203年，克烈（ᠬᠡᠷᠡᠶᠢᠳ / Хэрэйд）部首领王汗（ᠣᠩ ᠬᠠᠨ / Ван хан）与铁木真（ᠲᠡᠮᠦᠵᠢᠨ / Тэмүжин）反目，击溃了他的军队。铁木真带着少数追随者逃到东方一个泥泞的湖泊班朱尼（ᠪᠠᠯᠵᠤᠨ᠎ᠠ / Балжуна），被追杀得几乎全军覆没。据说他们在那里杀了一匹野马充饥，铁木真举起一杯浑浊的湖水发誓，要与追随他的人同甘共苦。这些“同饮班朱尼河水”的人终生受到尊崇。",
  "mongols:triumph": "想象：秋天，骑手们在漫长的征战之后穿过草原回家。营地里的人远远就看见了扬起的尘土和马尾苏勒德（ᠰᠦᠯᠳᠡ / сүлд）。妇女们端着一碗碗马奶酒（ᠠᠶᠢᠷᠠᠭ / айраг）走出蒙古包（ᠭᠡᠷ / гэр），向天空弹洒奶滴祈求吉祥，老人们一张张脸地清点着人数。那天夜里，一位歌手拉起马头琴（ᠮᠣᠷᠢᠨ ᠬᠤᠭᠤᠷ / морин хуур），长调一直唱到星光褪去。",
  "mongols:build": "13世纪50年代，佛兰德修士鲁布鲁克的威廉来到蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）都城哈拉和林（ᠬᠠᠷᠠᠬᠣᠷᠣᠮ / Хархорум），拜访蒙哥汗（ᠮᠥᠩᠬᠡ / Мөнх хаан）的宫廷。他看到一棵由被俘的巴黎金匠纪尧姆·布歇打造的银树：四条蛇盘绕其上，分别流出一种饮料，葡萄酒、马奶、米酒和蜂蜜酒，树顶上的天使吹响号角，示意仆人们斟酒。来自世界各地的工匠一同建造了这座城市。",
  "mongols:voyage": "想象：每年春秋两季，一户蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人家都要拆下蒙古包（ᠭᠡᠷ / гэр），把毡墙和哈那装上牛车和骆驼，赶着畜群前往新的牧场。孩子们骑在羊背上走在前面；祖母们带着铁炉子坐在车上。他们在敖包（ᠣᠪᠣᠭ᠎ᠠ / овоо）前停下，绕行三圈，添上一块石头。最后一天，他们看见前方绿油油的河谷，全家人都唱起歌来。",
  "mongols:festival": "查干萨日（ᠴᠠᠭᠠᠨ ᠰᠠᠷ᠎ᠠ / Цагаан сар），即白月，是蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人的新年。马可·波罗写道，在白节时，忽必烈汗（ᠬᠤᠪᠢᠯᠠᠢ / Хубилай хаан）收到了十万匹白马，人人都穿白衣以求吉祥。在每座蒙古包里，家人们托着长辈的手臂向他们问安，摆出层层叠起的奶饼塔和煮熟的羊背，蒸上数百个包子（ᠪᠤᠤᠵᠠ / бууз），年轻人则依次拜访每一位亲戚。",
  "mongols:games": "仲夏的那达慕（ᠨᠠᠭᠠᠳᠣᠮ / Наадам）上要举行男儿三艺：摔跤（ᠪᠥᠬᠡ / бөх）、赛马和射箭。身穿敞胸短褂、脚蹬尖头靴的摔跤手在每场比赛前跳起鹰舞。赛马时，五到十二岁的孩子骑着光背马在草原上奔驰长达三十公里，一边向马儿唱歌。射手中也有女子，她们射击地上的皮靶，裁判每见射中便拖长声音高唱一声（ᠤᠤᠬᠠᠢ / уухай）。",
  "mongols:drought": "想象：一个干旱的夏天，草原上的草还没到盛夏就变黄了，水井一口接一口地干涸。一户蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）人家眼看着羊群日渐消瘦。父亲骑马出去一连几天寻找牧场，长老们在敖包（ᠣᠪᠣᠭ᠎ᠠ / овоо）前献祭，向长生天（ᠲᠩᠷᠢ / Тэнгэр）洒奶。最后他们远远迁到北方，在一处遥远的泉水边与其他人家会合，与陌生人分享水源。秋天下了雨；一半的羊羔已经死了。",
  "mongols:quake": "1905年7月23日，有记录以来最强烈的地震之一袭击了杭爱（ᠬᠠᠩᠭᠠᠢ / Хангай）山区：这就是博尔奈（Болнай）地震，震级约为八级，几天前刚刚发生过车车尔勒格（Цэцэрлэг）地震。一道长达数百公里的裂缝横贯草原。牧民们感到大地像波浪一样起伏，马匹摔倒，蒙古包（ᠭᠡᠷ / гэр）坍塌；由于人们住在毡帐而不是房屋里，死者很少。此后好几个星期，喇嘛们在寺院里诵经祈祷。",
  "mongols:winter": "想象：干旱的夏天之后来了白灾（ᠵᠣᠳ / зуд）：那是一个冰层把牧草封在雪下、牲畜无法啃食的冬天。一位蒙古（ᠮᠣᠩᠭᠣᠯ / Монгол）牧民用双手为羊群刨开冰壳，还把自己蒙古包的毡衬喂给它们。夜复一夜，气温降到零下四十度以下。牲畜一头接一头地死去。春天，一家人清点剩下的牲畜，焚烧刺柏净化营地，然后从头开始。",
  "mongols:plague": "1346年，金帐汗国（ᠠᠯᠲᠠᠨ ᠣᠷᠳᠤ / Алтан Орд）的札尼别汗（ᠵᠠᠨᠢᠪᠡᠭ / Жанибек）的军队正驻扎在克里米亚港口卡法城外，鼠疫席卷了营地。士兵们成千上万地死去，尸体堆积如山。围城被迫放弃。当时的一位作者声称死者被抛进了城墙，不过史学家们对此并不确定。疾病随船只传到了欧洲，也穿过草原传回了牧民的营地。",
  "mongols:wedding": "铁木真（ᠲᠡᠮᠦᠵᠢᠨ / Тэмүжин）九岁时，父亲带他去见德薛禅（ᠳᠡᠢ ᠰᠡᠴᠡᠨ / Дэй сэцэн），德薛禅曾梦见一只白海青把太阳和月亮送到他手上。他把女儿孛儿帖（ᠪᠥᠷᠲᠡ / Бөртэ）许给了这个男孩。多年后，铁木真回来娶了她。她的母亲送了一件黑貂皮袄作为给他家人的礼物。《秘史》（ᠮᠣᠩᠭᠣᠯ ᠤᠨ ᠨᠢᠭᠤᠴᠠ ᠲᠣᠪᠴᠢᠶᠠᠨ / Монголын нууц товчоо）讲述了这一切：新娘、梦境，还有那件貂皮袄，铁木真后来用它赢得了一位盟友。",
  // ── Jurchens: siege … wedding ──
  "jurchens:siege": "1233年，金朝最后一位皇帝金哀宗带着残余的朝廷逃到蔡州。蒙古和宋朝的军队包围了这座城。城内的女真守军吃完了马，接着吃马鞍和皮革，然后是能找到的一切东西。1234年1月，城墙被攻破之际，哀宗把皇位传给了将军完颜承麟，自缢而死。当了不到一天皇帝的承麟在巷战中被杀。士兵们战斗到了最后。",
  "jurchens:triumph": "1114年，女真首领完颜阿骨打率领约两千五百名战士起兵反辽，在宁江州击败了辽军。1115年，他又在出河店大破兵力远胜于己的辽军。骑手们带着马匹、铠甲和粮食回到按出虎水，各部族聚在一起欢庆。那一年，阿骨打宣布建立新国家，国号为金，取自那条名字意为“金”的河流。",
  "jurchens:build": "1189年至1192年，金朝在都城中都附近的永定河上修建了卢沟桥。它的十一个石拱承载着通往南方的道路；桥栏上排列着雕刻的石狮，每一只都不相同，多到形成了一句俗语：卢沟桥的狮子数不清。想象：女真监工和汉人石匠并肩劳作，和着共同的号子用绳索拖拉石块。马可·波罗后来称赞它是一座举世无双的桥。",
  "jurchens:voyage": "金朝征服中国北方之后，许多女真家庭从满洲的森林迁到南方的河北和山东平原，编为兵农合一的猛安谋克。想象：一户人家装好车子出发了，孩子们裹在毛皮里。一周又一周，他们向南行进，直到森林变成了麦田和有城墙的城镇。他们保留自己的语言一代人之久，然后慢慢学会了汉人的生活方式。",
  "jurchens:festival": "宋朝作者记载了女真人一种不寻常的习俗：新年之后，正月十六夜允许偷盗（放偷）。人们可以从邻居家拿走任何东西，车子、马匹，甚至一个愿意私奔的姑娘，谁也不会受罚。想象：年轻人笑着在雪中潜行，去偷邻居的酒坛和马鞍，第二天各家各户带着酒和糕饼挨家挨户地讨价还价，把自己的东西买回来。",
  "jurchens:games": "重五节时，金朝宫廷举行拜天之礼，然后射柳、击球。骑手们骑着快马，手持弯月形头的球杖，追逐一只小球冲向场地一端设立的球门。女真王子们以球技高超著称，每进一球都有鼓声响起。金世宗酷爱这项运动，大臣们为了他的安全恳求他不要再玩了。",
  "jurchens:drought": "想象：金朝末年，旱灾和蝗灾袭击了开封周围的土地。麦子在田里枯萎，难民涌入城中。女真士兵和汉人农民一样，在粮仓门口排队等着领粥。粮价涨得那么高，一件丝袍只能换几斤粮食。各家卖掉了家具，然后是冬衣，等待着一个没有带来雨水的秋天。",
  "jurchens:quake": "想象：冬天，松花江沿岸山中的一个女真村庄地面震动起来。积雪从屋顶滑落，木屋吱嘎作响，泥土砌的炕灶裂开了。各家跑到外面的寒风中。萨满击鼓安抚地神，猎人们挨家挨户地去看望老人。他们首先重砌炕灶，免得夜里的严寒夺走任何人的性命。",
  "jurchens:winter": "想象：长白山森林中的冬天漫长而残酷。女真人家住在半埋于地下的房屋里，靠炕取暖，那是一种让灶烟从中穿过的泥土台子，一家人一起睡在温暖的炕上。男人们踩着滑雪板和雪鞋去猎貂和鹿，女人们缝制毛皮，守着炉火不让它熄灭。严寒终于消退时，他们带着狗到河边去听冰裂的声音。",
  "jurchens:plague": "1232年春，蒙古围攻金朝都城开封之后，城内爆发了一场可怕的瘟疫。《金史》记载，五十天内从城门抬出了九十多万具棺材，还不算买不起棺材的穷人。医生李杲当时就在城中，他写道，这种病既源于传染，也同样源于饥饿和恐惧。金朝从此一蹶不振。",
  "jurchens:wedding": "宋人的记载描述了女真人的婚俗。年轻男子带着马和酒作为礼物到新娘家，在她家服役数年之后才把她娶回家。穷人家另有办法：女儿们沿路边走边唱歌，歌唱自己的容貌、手艺和家世，喜欢她歌声的男子就可以把她娶回家。想象：在婚宴上，宾客们用角杯饮酒，伴着鼓点跳舞。",
  // ── Khitans: siege … wedding ──
  "khitans:siege": "1122年，女真大军席卷辽朝疆土，辽朝最后一位皇帝天祚帝带着日渐稀少的随从逃进了夹山。他和他的契丹骑手们在那里的山谷中躲藏了三年，被追捕、受冻挨饿。水冻住了就吃雪，能找到野味时就吃野味。许多人悄悄离去；少数人依然忠心耿耿。1125年，天祚帝骑马出山，想去投奔党项，途中被俘。",
  "khitans:triumph": "想象：契丹骑手们夏季出征归来时，辽朝营地的人们穿过草原去迎接他们。皇帝在木叶山的祖庙前献上白马和青牛。缴获的马匹和财物在各部族之间分配。那天夜里，骑手们用银杯喝马奶酒和葡萄酒，鼓和琵琶奏响，武士们围成一圈跳舞，老人们则唱起往昔的胜利。",
  "khitans:build": "1056年，在辽朝治下，契丹人和他们的汉族工匠在应县建起了佛宫寺释迦塔。木塔高六十七米，建造时没有用一根铁钉，梁架全靠数十种相互咬合的斗拱支撑。近一千年来，它历经地震和战火而屹立不倒，是世界上最古老、最高的木塔。想象：木匠们每架起一层，都会唱起歌来。",
  "khitans:voyage": "1124年，辽朝灭亡之际，契丹王子耶律大石带着约两百名骑兵脱离出来，向西而去。他在可敦城召集部族和兵马；然后率领他们穿越中亚的沙漠和群山。1141年，他的军队在卡特万之战中获胜，他建立了西辽，即喀喇契丹。想象：在路上走了好几个月之后，契丹人看到了楚河青翠的河谷，搭起了帐篷。",
  "khitans:festival": "《辽史》描述了契丹人的新年。人们把糯米和白羊油揉成拳头大小的团子，每个帐篷四十九个。天亮之前，大家把团子从帐篷的窗口扔出去，然后清点：如果是双数，就奏乐设宴；如果是单数，就要让十二名巫师摇着铃铛、持着箭绕帐篷呼喊，同时在炉灶里爆盐，以吓走鬼怪（惊鬼）。",
  "khitans:games": "《辽史》记载，三月初三，契丹人举行射兔。他们用木头刻一只兔子立作靶子；骑手们策马驰过，向它射箭。最先射中的人获胜，输的人要跪下向胜者敬酒，胜者在马背上一饮而尽。他们还在草原上打马球（击鞠），契丹王子们以骑速闻名。",
  "khitans:drought": "想象：一个旱年烤焦了辽朝的草原，牧草早早枯死。契丹牧民赶着畜群从一处干涸的泉眼赶往另一处。皇帝主持瑟瑟仪，向柳枝射箭以召唤雨水，但天空依然晴朗。南部州县的农民颗粒无收。朝廷打开南京的粮仓赈济饥民，牧民们则宰杀体弱的牲畜取肉。",
  "khitans:quake": "1057年，一场大地震袭击了辽朝的南京（今北京）。《辽史》记载，城墙和民房倒塌，死伤数万人。幸存者在露天宿营，朝廷向伤者发放粮食和布匹。在佛寺里，僧人们日夜诵经。住在草原帐篷里的契丹人，以前很少害怕大地。",
  "khitans:winter": "每年冬天，辽朝皇帝都要把朝廷迁往广平淀的冬捺钵，那是一片积雪较薄的避风平原。皇帝的大帐四周环绕着由车辆和毡子围成的墙。契丹贵族们打猎、议事，牧民们则在暴风雪中挣扎着让牲畜活下去。想象：一户人家的畜群正在雪中死去，他们凿开冰洞饮马，向太阳神祈祷。",
  "khitans:plague": "想象：某年夏天，一种热病由南方来的商人带进契丹营地，蔓延开来。同住一顶帐篷的家人一起病倒。萨满们击鼓、焚烧刺柏，病人被转移到单独的帐篷里，营地也迁往新的牧场，把疾病甩在身后。皇帝下令从南京送来药物。死者按照契丹习俗被置于山中的树上。",
  "khitans:wedding": "辽朝皇帝只娶萧氏的女子，因此两个家族世世代代紧密相连。据记载，在辽朝的婚礼上，新娘家在帐篷门口的地上放一副马鞍，新娘进门时要跨过它：“鞍”与“安”同音。跨马鞍的习俗从契丹人传入了汉人的婚礼。想象：鼓声响起，宾客们喝着马奶酒直到天明。",
  // ── 楽 showcase: histories of each people's music ──
  "chinese:showcase": "明清音乐继承了前代的礼乐编钟、文人的古琴、唐代的琵琶和拉弦的胡琴，但它最大的发展在于戏曲。昆曲称雄明代舞台；到了清代，梆子腔和皮黄等地方声腔在北京融合成了京剧，以京胡为主奏。满洲宫廷宴乐把蒙古等各民族的音乐与雅乐并列。在城镇和乡村，唢呐班在婚礼和葬礼上吹奏，丝竹合奏也十分兴盛。这首乐曲中的二胡、琵琶、笛子、笙、古筝和阮，至今仍在演奏。",
  "shang:showcase": "商代音乐只能从安阳出土的遗物和甲骨文中了解，卜辞中提到了舞蹈、鼓和祭祖的献祭。考古发掘出土了有几个指孔的陶埙、石磬，以及成套的青铜铙，这种铙口朝上敲击。鳄皮蒙的鼍鼓在更早的新石器时代墓葬中就已出现。继商而起的周人在商代钟磬的基础上，创立了宏大的礼乐乐队。商代的旋律无一留存，所以这首乐曲是一种复原：埙领奏，编磬应和，配以铙和鼍鼓，还用了瑟等几件周代乐器作为替代。",
  "shu:showcase": "四川盆地在三星堆有自己的青铜文化，但其音乐大多只能从青铜器中推测。巴人敲击錞于，那是一种常以虎钮装饰的青铜钟形鼓，他们的战舞巴渝舞令汉朝宫廷印象深刻，后来成了宫廷舞蹈。四川出土的汉墓俑表现了击鼓说唱的艺人以及弹琴吹管的乐师。这一地区还以琴闻名：成都的司马相如以一曲琴歌赢得了卓文君，古琴的蜀派传承至今。在这首乐曲中，箫领奏，古琴应和，配以笙、编钟和錞于。",
  "wei:showcase": "黄河腹地是早期中国礼乐成形的地方，有周代的钟磬，也有收集在《诗经》中的歌谣。汉代军队和仪仗伴着鼓吹乐行进，乐队有鼓、角、排箫和横吹，其铙歌的歌词也被记录了下来。魏晋时期，竹林七贤之一的阮咸以一种圆形音箱的琵琶著称，这种乐器后来以他的名字命名为阮，箜篌也从西方传了进来。吹打乐至今仍在乡村节庆中演奏。这首乐曲用了横吹、阮、排箫和建鼓。",
  "wu:showcase": "长江下游有自己的青铜音乐：吴越之人铸造句鑃，一种口朝上持握的钟，越国墓葬中还有原始瓷制成的钟和磬。柔婉的吴歌和南方情歌（吴声歌曲）在南朝时被收集起来。明代歌唱家魏良辅把昆山腔加以改良，形成昆曲，以曲笛伴奏。江南的琵琶演奏者形成了自己的流派，苏州评弹艺人伴着琵琶和三弦说唱，江南丝竹乐队至今仍在上海和苏州的茶馆里聚会演奏。在这首乐曲中，琵琶领奏，曲笛应和，配以古筝和笙。",
  "zhu-xis-legacy:showcase": "宋代士人把音乐视为礼乐这一道德秩序的一部分。徽宗命人仿照一口古钟，为宫廷雅乐铸造新的编钟。朱熹著有论琴律的文字，他的《仪礼经传通解》保存了十二首《诗经》乐谱（风雅十二诗谱），据说传自唐代。文人们在书斋里弹奏古琴，用减字谱记写的琴谱让曲目得以流传。东亚各地的孔庙音乐都源于这次复兴，琴人们至今仍在演奏《潇湘水云》等宋代琴曲。这首乐曲以古琴和瑟，配以编钟和编磬。",
  "yamato:showcase": "古坟时代的音乐只能从器物中了解。陶土埴轮人像表现了膝上横放着琴的坐者，还有击鼓的人；在他们之前，弥生人铸造了青铜铃，即铜铎。六弦的和琴属于这一古老的本土层次，至今仍在神道仪式（御神乐）中演奏。5世纪至8世纪，来自朝鲜诸国和中国唐朝的乐师带来了新的乐器，在奈良和平安时代，这些乐器发展成了雅乐，有筚篥、笙和龙笛。正仓院至今仍收藏着奈良时代的乐器，雅乐今天依然在演奏。古坟时代的旋律已经失传；这首乐曲是以早期雅乐的音色进行的复原。",
  "sengoku-daimyo:showcase": "日本的武士音乐始于盲眼的琵琶法师，他们向武士和朝臣说唱《平家物语》。武士阶层扶持能乐，能乐的谣曲和能管成了武士教养的一部分。出征时，军队用法螺、鼓和钲来传递信号。在九州南部，萨摩琵琶作为一种用尚武叙事歌教育年轻武士的方式发展起来，同一世纪，三味线从琉球传入。萨摩琵琶、能乐以及山伏吹法螺至今仍在传承。在这首乐曲中，萨摩琵琶领奏，能管应和，配以篠笛和阵太鼓。",
  "choson:showcase": "古朝鲜（고조선）的音乐几乎无从知晓。半岛上的青铜时代墓葬出土了青铜铃和响器，例如八珠铃（팔주령），很可能是巫师摇动的。与这一地区相关的最古老的歌是《箜篌引》（공후인），见于中国文献：一位船夫看见一个白发老人渡河时溺水而死，他的妻子弹着箜篌唱起了哀歌，船夫的妻子丽玉（여옥）便把这首歌谱在了自己的箜篌（공후）上。后来的高句丽（고구려）墓葬壁画上有琴、长角、鼓和舞者，据说玄琴（거문고）就是在那里创制的。古朝鲜的旋律已经失传；这首乐曲是用玄琴、箜篌、鼓（북）和巫铃进行的复原。",
  "mongols:showcase": "草原上的音乐已有数千年历史，但早期记载很少：中国文献描述过游牧军队的号角声和鼓声，13世纪访问蒙古（Монгол）宫廷的鲁布鲁克的威廉看到，每当可汗饮酒，乐师们便奏起乐来。长调（уртын дуу）旋律舒缓宽广，与呼麦（хөөмий）一起在牧民中成长起来，成为歌唱马匹、山川和聚会的歌。马头琴（морин хуур）的来历见于传说：一匹心爱的马死后，它的鬃毛和骨头做成了第一把琴。佛教寺院又加入了长号和钹。如今，呼麦、长调和马头琴在草原上和音乐会舞台上随处可闻，伴有托布秀尔（товшуур）弹拨乐器和雅托噶（ятга）筝。",
  "jurchens:showcase": "生活在满洲森林和河流间的女真诸部，有着萨满和猎人的音乐。萨满手持单面鼓跳舞，腰间的铁腰铃随着旋转叮当作响；口弦在通古斯诸民族中流行。12世纪金朝统治北方时，宫廷接管了宋朝的礼乐乐器和宴乐，金代的院本和诸宫调十分兴盛；当时的墓俑表现了舞台上的演员和乐师。后来，满洲宫廷在其他音乐之外仍保留着萨满祭，萨满鼓和口弦至今仍在这一地区流传。在这首乐曲中，胡琴领奏，配以三弦和唢呐。",
  "khitans:showcase": "契丹人是流动的牧民，他们的皇帝在各季节的营地（捺钵）之间迁徙。10世纪建立辽朝之后，宫廷保留了几种音乐：继承自唐朝和后晋的雅乐与大乐，以及契丹人自己的国乐和鼓吹。宣化的辽墓壁画上有演奏琵琶、笙、笛、拍板和鼓的乐队。以邻近的奚人命名的拉弦乐器奚琴，成了后来朝鲜奚琴（해금）等胡琴类乐器的祖先。契丹的歌曲本身已经失传，所以这首乐曲是用奚琴、琵琶、胡笳和方响进行的复原。",
  // ── Ming–Qing: stories of the Ming and Qing centuries ──
  "chinese:gather": "1552年，蕲州的医生李时珍开始了他毕生的事业《本草纲目》。二十七年间，他背着竹篓走遍湖北、江西和江苏的山岭，向采药人、樵夫、猎人和渔夫请教，亲自挖掘根茎、品尝叶片。凡是旧本草书中有错的地方，他都一株一株地加以纠正。这部书在他去世后不久的1593年刊印出版，记载了近一千九百种药物，不久便传到日本，后来又传到欧洲。",
  "chinese:flood": "1565年至1592年间，明朝朝廷四次派潘季驯治理黄河。黄河不断淤积、决堤，堵塞了向北方运粮的大运河。他的办法是束水攻沙：修筑狭窄而坚固的堤坝，让河水流得湍急，把自身的泥沙冲进大海。数以万计的民夫沿河堤搬运泥土、石块和成捆的高粱秆，唱着号子保持步调。此后多年黄河安澜，运粮船又能向北航行了。",
  "chinese:fire": "1626年5月30日早晨，北京西部的王恭厂火药局发生爆炸。雷鸣般的巨响滚过全城，一团黑云升上天空，火药局周围的整片街巷房屋被夷为平地。年轻的天启帝正在宫中用早膳，在纷纷坠落的屋瓦中奔逃避险。大火在巷子里蔓延，一连几天，人们都在瓦砾中寻找家人。谁也不知道爆炸的起因，北京人把那天早晨的种种怪谈讲了好几代。",
  "chinese:siege": "1626年正月，后金的创建者努尔哈赤率领大军越过封冻的辽河，进攻有城墙的小城宁远。明朝守将袁崇焕把城外百姓迁入城内，烧掉城墙外的房屋，让进攻者无处藏身，并在城头架起仿照葡萄牙样式铸造的重炮，即红夷大炮。一连几天，进攻者冒着炮火挖掘冻硬的城墙。随后他们撤退了。在漫长的戎马生涯中，努尔哈赤第一次被击退。",
  "chinese:triumph": "1697年，康熙帝第三次亲征噶尔丹，这位准噶尔汗他已在大漠中追击了多年。整个征途中，他不断写信回宫，讲述饮食、马匹、风沙和寒冷。夏天传来噶尔丹已死的消息，他的家书变得欢欣鼓舞。他回到北京时，王公大臣们骑马出城迎接，八旗的鼓角奏响了凯旋的铙歌，朝廷祭告天地和祖先。",
  "chinese:festival": "晚明的张岱写道，中秋之夜，整个苏州的人都登上虎丘：士绅和优伶，婢女和名妓，船夫和店伙，都把席子铺在那块巨大的平石上。起初，上千人和着锣鼓一同歌唱。夜色渐深，锣鼓声停了，只剩下丝竹；然后只有最好的歌者一个接一个地唱起舒缓的昆曲。将近午夜，一个人独自站起来，不用任何乐器清唱，整座山都屏住了呼吸。",
  "chinese:games": "1425年至1435年在位的明宣德帝酷爱斗蟋蟀，人们称他为蟋蟀皇帝。苏州的官员奉命把最凶猛的蟋蟀送进宫里，一只常胜的蟋蟀能值一匹马。约1680年，蒲松龄讲了一个与此有关的悲伤故事《促织》：一个穷人的儿子不小心弄死了家里最好的蟋蟀，他的魂魄变成了一只小小的、无所畏惧的蟋蟀，打败了所有对手。北京的男人们直到后来仍整个冬天把蟋蟀装在葫芦里揣在怀中。",
  "chinese:winter": "在北京，冬天是按“九”来数的（数九）：从冬至起，九个九天，直到寒冷消退。为了熬过这段日子，清代人家会挂一张九九消寒图。据说道光帝写过一幅，用九个字“亭前垂柳珍重待春風”，每个字九画，以双钩描出轮廓。每天早晨用墨填上一笔，等到第八十一笔填完，春天就到了。孩子们一边走一边唱着九九歌：三九四九，冰上走。",
  // ── Edo: stories of the Edo age ──
  "japanese:battle": "1615年夏，在大坂，两个半世纪太平岁月之前的最后一场大战打响了。真田信繁，后世称为幸村，率领他身着红色铠甲的骑兵（赤备え）径直冲向天王寺附近德川家康的本阵。他们三次突破防线；家康的马印倒下了，据说他甚至想过自尽。随后冲锋的力量耗尽了。精疲力竭的真田坐在安居神社休息，在那里被杀。连他的敌人也称他为日本第一兵（日本一の兵）。",
  "japanese:voyage": "1782年，货船神昌丸载着运往江户的大米从伊势的白子起航，遭遇了风暴。它漂流了八个月，船长大黑屋光太夫和船员们最后漂到了阿留申群岛的阿姆奇特卡岛。他们穿越堪察加和西伯利亚，1791年，光太夫在圣彼得堡跪在叶卡捷琳娜大帝面前，请求回国。她答应了。1792年，一艘俄国船把他送到了根室。当初出航的十七个人中，只有三人再次见到了日本。",
  "japanese:rain": "1857年，歌川广重出版了《大桥安宅骤雨》（大はしあたけの夕立），这是他的《名所江户百景》之一。灰色的雨线斜斜地划过整个画面；几个人披着蓑衣、打着伞匆匆走过木桥，对岸消失在倾盆大雨之中。每个江户市民都熟悉那样的夏日傍晚骤雨。三十年后，梵高在巴黎用油彩临摹了这幅版画，连雨丝也一起画了下来。",
  "japanese:drought": "随着江户发展成为世界上最大的城市之一，饮用水开始短缺，干旱的夏天里井水变得咸涩。1653年，幕府雇用庄右卫门和清右卫门兄弟从多摩川引水。他们的工人在约八个月里，从羽村挖出一条四十多公里长的水渠，全程落差只有几米。传说钱用光时，兄弟俩卖掉了自己的房子。玉川上水为这座城市供水达三个世纪，兄弟俩也被赐姓玉川。",
  "japanese:thunder": "17世纪初，京都画家俵屋宗达画了一对金地屏风《风神雷神图屏风》。左边，绿色皮肤的雷神驾着乌云跃过金色的背景，敲击着环绕在背后的一圈鼓；右边，风神咧嘴笑着，背着装满风暴的口袋。一个世纪后，尾形光琳临摹了这对屏风，再后来酒井抱一又临摹了光琳的作品。每一位画家都以自己的方式回应了云中的那位鼓手。",
  "japanese:wedding": "江户的婚礼在新郎家举行，常常在傍晚。新娘身穿白衣到来，脸半遮着，新人以三三九度定下婚约：从三只叠放的漆杯中各啜饮三口。然后一位家族宾客站起来吟唱《高砂》，这首能乐唱的是一对化为两棵松树之精的老夫妇：“高砂や、この浦船に帆を上げて”，在这只小船上扬起风帆。唱词祝愿新人白头偕老，像松树一样一同老去。",
  "japanese:showcase": "江户时代是日本町人音乐的鼎盛时期。三味线于16世纪由琉球三线改制而成，成了歌舞伎的声音；从1684年起，竹本义太夫用粗杆三味线伴奏，说唱近松门左卫门的人形净琉璃。盲人大师八桥检校塑造了《六段》等独奏筝曲，盲人行会把筝、三味线和胡弓合在一起演奏。普化宗的虚无僧戴着竹编斗笠云游四方，把吹奏尺八当作修行。由篠笛和太鼓组成的祭典乐队在神田祭和山王祭上沿街演奏。",
  // ── Joseon: stories of the Joseon age ──
  "koreans:triumph": "朝鲜（조선）的年轻书生考中科举（과거）后，国王的人会在他的帽子上插一朵纸花，即御赐花（어사화）。随后是三日游街（삼일유가）：新科及第者骑马穿过汉阳（한양）的街道，前面有吹管击鼓的乐手，还有翻跟头唱歌的广大（광대）艺人和杂技演员，邻居们挤着来看。他拜访老师和长辈，最后回到家乡参加村宴。人们说，盘索里（판소리）就是从这些艺人的歌中发展起来的。",
  "koreans:quake": "《朝鲜王朝实录》（조선왕조실록）记载，1518年夏，中宗（중종）在位时，一场大地震袭击了汉阳（한양）。声如雷鸣，房屋摇晃得像要倒塌，城墙多处开裂坍塌。人们逃出家门，在露天过夜，不敢回到屋顶下，余震持续了好几天。国王和大臣们忧心忡忡地追问，是国中什么过失撼动了大地，朝廷也削减了宴饮。",
  "koreans:flood": "每年夏天，流经汉阳（한양）的清溪川（청계천）都会淤满泥沙，淹没两岸穷人的房屋。1760年，英祖（영조）下令疏浚（경진준천）。在五十七天里，约二十万人挖掘河床，用石头砌筑河岸；有些人领工钱，有些人是自愿前来的。年迈的国王亲自到五间水门（오간수문）观看施工，并与劳工们交谈。此后设立了一个新的官署负责保持河道畅通，还为主持工程的官员们绘制了描绘这次工程的画作。",
  "koreans:fire": "1426年二月，世宗（세종）离开都城期间，汉阳（한양）发生火灾，强风把火势吹过集市附近拥挤的街道。两千多间房屋被烧毁，有人被烟呛死。世宗急忙赶回，设立了禁火都监（금화도감），一个防火的官署：在房屋之间开辟防火带，沿街设置水井和水缸，并组织人员救火。它被视为朝鲜第一支消防队。",
  "koreans:showcase": "朝鲜（조선）的音乐有两种生命。在宫廷，世宗（세종）和学者朴堧（박연）改革了雅乐（아악），世宗本人被认为创作了《与民乐》（여민락）和宗庙祭礼的音乐。《乐学轨范》（악학궤범，1493年）画出了每一种乐器。在后来的几个世纪里，音乐走进了乡村和集镇。盘索里（판소리）歌手伴着一面鼓（북）讲述长篇故事，男寺党（남사당）等巡回戏班表演舞蹈和杂耍，农民的风物（풍물）乐队用小锣（꽹과리）、大锣（징）、杖鼓（장구）和太平箫（태평소）在劳作和节庆时演奏。19世纪90年代，金昌祖（김창조）为伽倻琴（가야금）创立了散调（산조）。",
  // ── Han, Zhou–Han: stories of the Zhou and Han ages ──
  "chinese-early:showcase": "1978年，考古学家打开了约葬于公元前433年的曾侯乙墓，发现了一整支乐队：髹漆架上的六十五件青铜编钟，每件都能发出两个音，还有编磬、瑟、笙、排箫、篪和鼓。周代统治者相信礼乐维系着天下的秩序；孔子听到古老的韶乐，三月不知肉味。《诗经》中的歌就是伴着这样的乐器演唱的。汉武帝时，由李延年主持的汉朝宫廷乐府从各地收集民歌，并创作新的颂歌。",
  "chinese-early:hunt": "约公元前135年，诗人司马相如为汉武帝写下了《上林赋》，描绘长安以西的皇家猎苑。黎明时分战车隆隆驶出，旌旗遍布山谷，驱兽者把虎豹和鹿从林中赶出，射手们把飞鸟射落天空。然后围猎以宴会结束：钟鼓齐鸣，各地的歌者轮番献艺，舞者翩翩起舞。到了最后，天子感叹这一切太过奢靡，便把猎苑开放给了农民。",
  "chinese-early:battle": "公元前204年，汉将韩信穿过狭窄的井陉关，进攻兵力远胜于己的赵军。他做了一件不可思议的事：让一万人背靠河水列阵，无路可退。赵军冲出营垒想要消灭他们；陷入绝境的汉军拼死作战。与此同时，两千骑兵溜进空虚的赵营，在营墙上插满了汉军的红旗。赵军见状大乱。背水一战从此成了成语。",
  "chinese-early:siege": "传说在公元前5世纪，工匠公输班为楚国造了新的云梯，准备攻打小国宋国。主张兼爱、谴责攻伐之战的哲学家墨子，走了十天十夜去见楚王。在楚王面前，墨子解下腰带当作城墙，用木片当作器械。公输班用他的模型进攻了九次；墨子九次都守住了。他还说，他的弟子们早已守在宋国的城墙上。楚王于是取消了这场战争。",
  "chinese-early:triumph": "公元前101年，经过漫长而代价高昂的远征，汉军从费尔干纳的大宛带回了汉武帝梦寐以求的著名汗血马。武帝欣喜若狂，命人作了一首颂歌《天马歌》，由乐府在朝廷的大祭上演奏：天马来兮从西极，经万里兮归有德。汉代乐师伴着钟鼓唱起这首歌，那个时代的墓葬中还铸有疾驰的铜马。",
  "chinese-early:gather": "《诗经》中有一首《芣苢》，写的全是妇女采集的情景。采采芣苢，薄言采之；采采芣苢，薄言有之。一章又一章，她们摘下籽粒，捋下茎叶，装满衣襟，掖起衣裾把收获带回家。周代的歌者一遍遍重复这些句子，正如妇女们在田里一遍遍重复她们的劳作，两千年后学者们还在争论这种植物能治什么病。这首歌本身却无需解释：它是阳光下一起劳作的声音。",
  "chinese-early:build": "约公元前256年，秦国的蜀郡守李冰着手阻止岷江淹没成都平原。在都江堰，他的工人在江心筑起鱼嘴分水堤，把江水一分为二，又用火烧和冷水浇激的方法在坚硬的岩石上凿开一条渠道，把一半江水引入田地。他们没有铁器炸药，只有火、水、镐头和装在竹笼里的石块。这套系统至今仍在灌溉平原，人们至今仍在江边的庙宇里纪念李冰和他的儿子。",
  "chinese-early:voyage": "公元前138年，张骞奉汉武帝之命，带着约一百人和一位名叫甘父的向导从长安向西出发，去寻找遥远的月氏。没过几天，他就被匈奴俘获。他在匈奴生活了十年，娶妻生子，却始终持着皇帝授予的节杖。最终他逃了出来，翻越帕米尔高原，到达了月氏和大夏。离开十三年后，他只带着甘父回到了长安，却满载着关于汉人从未见过的骏马、葡萄和城市的见闻。",
  "chinese-early:festival": "《诗经》中郑国的一首歌唱道，春天，溱水和洧水因融雪而涨满。按照习俗，青年男女手持兰草来到河边，洗去冬天的晦气。姑娘说：去看看吗？小伙子说：我已经去过了。那就再去一趟吧。洧水那边地方宽广又快乐。他们一起说笑，互相赠送芍药。后来的汉代作者把这称为三月的上巳节。",
  "chinese-early:games": "蹴鞠，即踢一种塞满羽毛或毛发的球，在汉代是士兵的游戏。史学家司马迁写到年轻的将军霍去病：在长城以外征战时，他的士兵缺粮，几乎站不起来，他却让人清理出一块场地来踢球。司马迁对此不以为然。但汉代的兵书把蹴鞠列为兵技之一，墓葬画像石上刻着带球跃起的球员，无论宫廷还是市井，人们都会聚拢来看一位踢球好手。",
  "chinese-early:ritual": "公元前110年，汉武帝登上泰山，向天地举行封禅大典，这一礼仪古老到已经没有人确切记得该怎么做了。太史令司马谈在途中病倒，无法继续前行。临终时，他对儿子司马迁说：天子举行封禅大典，而我却不能随行，这是命啊。他嘱咐儿子完成他开始写作的史书。司马迁答应了，写成了《史记》。",
  "chinese-early:rain": "约公元前130年，汉代学者董仲舒写道，天不下雨时，各地官员都应当祈雨。他在《春秋繁露》中的指示十分细致：关闭城的南门、打开北门，禁止用火，用泥土塑一条大龙，旁边再放几条小龙，让儿童八人一组在祭坛前跳舞。女人应当欢乐，男人应当安静。在整个汉朝天下的村庄里，人们塑起泥龙，等待云来。",
  "chinese-early:drought": "《诗经》保存了一位周王在大旱中的声音。在《云汉》一诗中，周宣王仰望晴朗无云的夜空。他说，旱灾太严重了，炎热像火一样炙烤。我向每一位神灵献祭，从不吝惜牺牲；我献出了所有的玉器和丝帛，却仍然没有谁听见我。周朝的百姓，恐怕一个也剩不下了。这首诗没有以下雨结尾，只有一位不停地为百姓祈祷的君王。",
  "chinese-early:flood": "公元前132年，黄河在瓠子决口，淹没了十六个郡。二十多年间，河水四处横流。公元前109年，汉武帝亲临决口。他命令将军以下的所有官员亲手背负柴草，还砍伐皇家园林中的竹子来筑坝。他望着河水，作了《瓠子歌》，请求河神回归故道。决口终于被堵上，人们在上面修建了宣房宫。",
  "chinese-early:wind": "公元前195年，汉朝开国皇帝刘邦在征战归来的途中，路过家乡沛县。他召集故人和父老设宴，又召集了一百二十名少年唱歌。酒过数巡，他亲自击筑而歌：大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方！随后他起身起舞，泪流满面。这就是《大风歌》。",
  "chinese-early:thunder": "汉代大多数人相信，雷是上天在惩罚恶人：被雷劈死的人一定隐藏着什么过错，也许是给人吃了不洁的食物。约公元80年，学者王充在《论衡》中表示了不同意见。他写道，雷是火：被雷击中的人会被烧焦，空气中有焦糊味，石头也被烤焦。它来自夏天阴阳二气的相激，而不是来自一位击鼓的愤怒神灵。当时很少有人听他的，但他审慎的怀疑使他成为中国最早的理性之声之一。",
  "chinese-early:quake": "132年，太史令张衡向汉朝宫廷展示了一件青铜仪器，形如酒尊，周围有八条龙，每条龙口中衔着一颗铜珠，下方各有一只张着嘴的蟾蜍。138年的一天，西边那条龙口中的铜珠掉了下来，而都城洛阳却没有任何人感觉到震动。朝臣们嘲笑这台机器。几天后，一名骑使从遥远西方的陇西赶来，报告发生了大地震。史书记载，从那以后，朝廷开始记录每次地震的方向。",
  "chinese-early:winter": "公元前100年，汉朝使者苏武被匈奴扣留，他不肯投降，匈奴便把他关进一个空地窖，不给食物。天下起了雪，他躺在那里嚼着雪和毡衣上的毛，活了下来。匈奴又把他送到冰封的北海（贝加尔湖）边牧羊，说等公羊产奶时就放他回去。他挖野鼠储藏的草籽充饥，手持使节的符节，直到节上的旄毛全部脱落。十九年后他回到了故国，头发已经全白。",
  "chinese-early:plague": "汉朝末年，瘟疫一次又一次地席卷全国。医生张仲景写道，十年之内，他那个两百多人的宗族死了三分之二，大多死于伤寒。他悲痛之余，钻研古代医书和自己的病例，写成了《伤寒杂病论》，医生们至今仍在研读。后世传说，某年冬天他用面皮包裹羊肉和草药，捏成耳朵的形状，来治疗穷人冻伤的耳朵，饺子就是这样来的。",
  "chinese-early:birth": "《礼记》讲述了周代人家如何迎接新生儿。生男孩，就在门的左边挂一张弓；生女孩，就在门的右边挂一块佩巾。第三天，男孩被抱出来，一名射手向天、地和四方射出六支箭。《诗经》中的一首歌说得更多：生了儿子，让他睡在床上，给他玉璋玩；生了女儿，让她睡在地上，给她陶制的纺锤。这些话并不平等；但迎接新生命的喜悦是一样的。",
  "chinese-early:wedding": "约公元前140年，贫穷而默默无闻的诗人司马相如应邀参加临邛富有的冶铁商卓王孙举办的宴会。卓王孙的女儿卓文君新近守寡，喜爱音乐，她在屏风后听司马相如弹琴，唱起《凤求凰》。当夜她便和他私奔到了成都，他家里家徒四壁。后来他们回到临邛开了一家酒铺；她当垆卖酒，他洗涤酒器，她的父亲终于让步了。",
  "chinese-early:death": "哲学家庄子的妻子去世时，他的朋友惠子前来吊唁，却发现他岔开双腿坐在地上，敲着盆唱歌。惠子大为震惊：她与你一起生活，为你养育子女，与你一同变老。你这样不是太过分了吗？庄子回答说，起初他也和别人一样悲伤。但在她有生命之前并没有形体，后来有了气，然后有了身体；如今她又变化了，就像春天变成秋天。她正安睡在天地这间大屋子里。我为什么要哭号呢？",
  // ── Han, Sui–Tang–Song: stories of the Sui, Tang and Song ages ──
  "chinese-middle:showcase": "隋唐宫廷宴乐由十部伎演奏，各以其故乡命名：龟兹、疏勒、安国、天竺、高丽等，与中原乐曲并列。中亚乐师带来了曲项琵琶、箜篌、筚篥和羯鼓，唐玄宗酷爱亲自击打羯鼓。他在梨园训练了数百名乐工，《霓裳羽衣曲》成了那个时代最著名的乐曲。敦煌的琵琶谱至今仍有留存。在宋代的城市里，瓦舍勾栏中的歌者演唱词，诗人姜夔于1202年记下了他自己创作的曲调。",
  "chinese-middle:hunt": "唐朝女皇武则天之子章怀太子于706年改葬时，画师们在他位于长安附近的墓道墙壁上绘制了一幅宏大的《狩猎出行图》。四十多名骑手在树下疾驰，旌旗飘扬；驯鹰人臂上架着猎鹰，一条猎犬跟着马奔跑，一位骑手身后的马鞍上还蹲着一只从中亚带来的斑点猎豹。骆驼驮着给养跟在后面。画师们画出了唐代贵族的所爱：快马、旷野，以及一同游猎的一天。",
  "chinese-middle:battle": "1140年夏，宋将岳飞在郾城迎战金军骑兵。金军派出重甲骑兵，据说是三匹一组用铁链连在一起，谁也不能后退。岳飞派出手持长柄大斧和钩镰的步兵，钻到马下砍马腿；一匹马倒下，与它相连的马也随之倒下。战斗一直持续到天黑，金军撤退了。金兵事后说：撼山易，撼岳家军难。",
  "chinese-middle:gather": "约760年，由僧人抚养长大的孤儿陆羽写成了《茶经》。他说，茶应在二月至四月间采摘，要在晴天早晨、叶上还带着露水时采，雨天和阴天都不采。最好的茶野生于烂石之间；其次生于砾壤之中。他描述了采茶人如何背着竹篮上山，茶叶又如何经过蒸、捣、拍成饼、烘干，再用绳子串起来。后来唐代的茶肆把陆羽像供奉为茶神。",
  "chinese-middle:build": "约600年，隋朝一位名叫李春的工匠在赵州的洨河上建造了一座石桥。他没有采用高高的半圆形拱，而是造了一个跨度三十七米的长而扁平的大拱，并在拱肩上开了四个小拱，让洪水可以从中通过，也减轻了桥身的重量。十四个世纪以来，它历经洪水和地震，一直承载着行人、车辆和驴子。后来的民歌说是仙人鲁班一夜之间造成了这座桥，桥上的驴蹄印是一位神仙过桥时留下的。",
  "chinese-middle:voyage": "742年，日本僧人来到扬州拜见唐朝高僧鉴真，恳求他派人去日本传法。没有人愿意去，他便决定亲自前往。他五次尝试东渡：被官府阻拦，船只遇难，有一次风暴竟把他们一路吹到了海南。在归途中，他的日本弟子去世了，鉴真也双目失明。753年，第六次东渡时，六十六岁的他终于抵达日本，在奈良创建了唐招提寺。寺中至今仍供奉着他闭目而坐的塑像。",
  "chinese-middle:ritual": "873年春，唐懿宗命人从法门寺迎请佛指骨舍利到长安。沿途数里，道路两旁排满了丝绸华盖和香炉；僧人诵经，乐队奏乐，人们剪下头发、炙烧手臂以示虔诚。数月之后，舍利被送回寺中，连同金银宝函、来自西方的玻璃器和最精美的茶具一起封入地宫。1987年修缮古塔时，地宫被打开，所有这些都在唐人留下它们的地方被找到了。",
  "chinese-middle:rain": "约851年，远在巴山中的诗人李商隐收到一封信，问他何时归来。那天夜里下着雨，他写下了一首最受喜爱的唐代短诗：君问归期未有期，巴山夜雨涨秋池。何当共剪西窗烛，却话巴山夜雨时。从那以后，夜雨总让中国的读者想起远方的某个人。",
  "chinese-middle:drought": "1050年，吴地全境歉收，杭州知州范仲淹做了一件奇怪的事。他除了发放粮食之外，还鼓励在西湖上举行竞渡，并亲自出去观看，又劝佛寺趁工价低廉大兴土木，同时重修了粮仓和官署。批评者说他在饥荒中浪费钱财。他回答说，竞渡和营建让数以万计原本会饿死的穷人有饭吃、有工钱拿。科学家沈括记载，那一年杭州比周边任何地方都度过得更好。",
  "chinese-middle:flood": "1077年秋，黄河决堤，洪水包围了徐州，水位比城内的街道还高。时任知州的诗人苏轼阻止富人出逃，说他们一走，所有人都会恐慌。他搬进城墙上的一间草棚，亲自到军营请士兵们帮忙，冒雨带领他们修筑了一道长堤。七十天里他都没有回家。洪水退去后，他在城墙上修建了黄楼，全城在那里设宴庆祝。",
  "chinese-middle:wind": "761年八月，一场秋天的狂风掀走了诗人杜甫成都郊外草堂屋顶上的三重茅草。村里的孩子们抱着茅草跑了，他在后面喊得声嘶力竭。那天夜里雨水从屋顶漏下，淋湿了他的被褥，孩子们睡在又湿又冷的被子里。在《茅屋为秋风所破歌》中，他希望有广厦千万间，庇护天下所有的寒士，并说如果能见到这样的房子，即使自己独自冻死也心甘情愿。",
  "chinese-middle:fire": "孟元老回忆宋朝都城开封时，描述了这座城市如何防火。每隔几百步就有一座军巡铺，士兵们在夜间巡逻；高处建有砖砌的望火楼，日夜有人瞭望。楼下的消防队备有水桶、绳索、梯子、斧头和湿麻搭。一旦发现火情，骑兵便飞奔报告军厢，士兵们跑来灭火，不向住户要一文钱。数十万人就生活在这样的守护之下。",
  "chinese-middle:thunder": "在遥远的南方雷州半岛，夏天几乎每天都有雷暴。唐代雷州人说，他们的第一位刺史陈文玉是从一枚巨卵中诞生的，那枚卵是一场雷雨之后被猎人的狗发现的，他是雷神之子。他去世后，人们为他建庙，奉为雷祖。唐代作者记载，那里的人们为雷神备有鼓，并献上祭品，祈求风暴不要伤害他们的田地。",
  "chinese-middle:quake": "734年二月，一场大地震袭击了秦州，即今天水一带，位于从长安西去的路上。唐代史书记载，房屋和城墙倒塌，四千多人被压死，其中包括官员。唐玄宗派一位大臣前去慰问幸存者：失去亲人的家庭得到丝绸和粮食，死者由官府出资安葬，失去一切的人被免除了赋税。这座城镇在附近的新址上重建。",
  "chinese-middle:plague": "唐代医生孙思邈拒绝了三位皇帝授予的官职，用漫长的一生为病人治病、收集药方。652年，他完成了《千金要方》，他说之所以这样命名，是因为人命至重，有贵千金。他教导说，大医必须对富人和穷人、亲友和陌生人一视同仁，无论何时，不避昼夜寒暑、饥渴疲劳，都要出诊，对病人绝不能心生嫌恶。瘟疫流行时，他的书提供了人人都能配制的方子。",
  "chinese-middle:birth": "据作者们回忆，在宋代的城市里，婴儿出生第三天和满月时都要举行洗儿会。亲戚们围着一盆香汤，把铜钱和果子扔进去，用发钗搅动，然后给婴儿洗澡、剃胎发。1083年，儿子苏遁出生时，正谪居黄州的诗人苏轼为洗儿写了一首戏谑的诗：人皆养子望聪明，我被聪明误一生。惟愿孩儿愚且鲁，无灾无难到公卿。",
  "chinese-middle:wedding": "唐代的婚礼有许多好玩的习俗。黄昏时新郎来到新娘家，女方家的女眷们拦住大门戏弄他，他得高声吟诵催新娘快点梳妆的诗（催妆诗），新娘才肯出来。回去的路上，邻居们拦住道路（障车）唱歌，直到得了酒食才放行。随后新人进入院中搭起的青布帐篷（青庐），这是仿照北方民族的做法。新郎的朋友们载歌载舞，一直闹到深夜。",
  "chinese-middle:death": "809年，唐代诗人元稹失去了年轻的妻子韦丛，她在他贫寒时嫁给了他。在三首《遣悲怀》中，他回忆她如何翻箱倒柜为他找衣服，拔下金钗为他换酒，拾取落叶当柴烧。他写道，如今他有了丰厚的俸禄，却只能在祭奠时献给她。这种悲伤人人都懂；但对于一对同甘共苦的贫贱夫妻来说，每一段回忆都令人心痛。",
  // ── Japanese, Heian: stories of the Heian court ──
  "japanese-early:showcase": "雅乐在奈良时代从唐朝、朝鲜等地传入日本，在京都的平安朝廷中被分为两部分：左方的唐乐，源自中国和印度；右方的高丽乐，源自朝鲜。838年，藤原贞敏随遣唐使船队前往唐朝，带回了从扬州一位名师那里学到的琵琶曲。贵族们在月夜宴会上演奏管弦，筚篥、龙笛和笙配以琵琶和筝，还演唱催马乐民歌和朗咏诗歌。《源氏物语》中满是这样的音乐，宫内厅的乐师们至今仍在演奏。",
  "japanese-early:hunt": "《伊势物语》记载，惟乔亲王每年春天都去水无濑的别墅，骑马到交野的原野上放鹰狩猎。他总是带着诗人在原业平和其他朋友同行。但他们很少真正打猎，而是坐在渚院的樱花树下饮酒作歌。业平写道：世上若无樱花在，春心该是何等安闲。对平安时代的贵族来说，狩猎只是走进花海的一个理由。",
  "japanese-early:siege": "1062年，在日本遥远的北方，源赖义和他的儿子义家围攻了据守厨川栅的安倍氏。他们用柴草填满壕沟并点燃，栅寨燃起了大火。一个古老的故事说，此前在衣川，义家追击安倍氏首领贞任，在他身后喊出了半首和歌：衣襟的经线已经绽开了。贞任在马上回过身来，接上了后半首：多年的纠缠已将它们磨损。义家大为倾倒，放下弓，放他走了。",
  "japanese-early:triumph": "七月，平安朝廷举行盛大的相扑节会，从各国召集来的力士被分为左右两队。胜负以音乐宣告。左方获胜时，左方乐师奏乐，一位舞者戴着武将王子兰陵王的镀金面具出场，踏步欢庆；右方获胜时，两位舞者表演纳曾利，即一对龙。身穿丝绸的朝臣们在宫殿的楼阁中观看，获胜队的官员们得到了酒和赏赐。",
  "japanese-early:gather": "新年的第一个子日，平安朝臣们到京都周围的田野里采摘嫩菜（若菜摘み），煮成羹汤，以保全年无病。光孝天皇即位之前，曾随这样一份礼物写了一首和歌：为君出春野，采摘嫩菜时，雪花纷纷落，飘满我衣袖。这首歌收在《百人一首》中。这一习俗至今仍保留在正月初七的七草粥里。",
  "japanese-early:build": "1053年，藤原赖通在宇治的平等院落成了凤凰堂，那是倒映在池中的阿弥陀西方极乐世界的景象。堂内，雕刻家定朝和他的工坊雕刻了金色的阿弥陀佛像，以及沿墙排列的五十二尊乘云的小菩萨（云中供养菩萨）。其中许多正在奏乐：鼓、笛、笙、琵琶、竖琴和钹；其他的则在起舞。平安时代的贵族相信，佛陀会伴着这样的音乐降临，在他们死时接引他们的灵魂。",
  "japanese-early:festival": "四月里，贺茂祭使京都热闹非凡，人人都用葵叶装饰车子和帽子。《源氏物语》对此有生动的想象：街上拥挤不堪，车辆为了争抢观看游行的位置互不相让。六条御息所悄悄前来，想看一眼骑马经过的源氏，但他的妻子葵上的仆从们把她朴素的牛车推到后面，还折断了车辕。她受尽屈辱，眼看着他经过，却没有得到一瞥。日本人至今每年五月仍举行葵祭。",
  "japanese-early:games": "平安贵族玩蹴鞠，在由樱、柳、枫、松四棵树围出的场地里，用脚让一只鹿皮球不落地。它没有输赢，只有长时间优雅的连续传踢。12世纪的藤原成通是蹴鞠大师：据说他练了七千天，能一边沿着栏杆行走一边踢球。传说有一次，球的精灵以三个猴脸孩子的模样出现在他面前，告诉了他它们的名字。",
  "japanese-early:ritual": "每年秋天的新尝祭上，平安时代的天皇把新米献给众神，从贵族家庭中选出的四五名少女在他面前跳五节舞，长袖翻转五次。传说它起源于天武天皇弹琴时，天女们降临为他起舞。僧人歌人遍昭写道：天风啊，请吹闭云中的通路，让这些少女再多留片刻。如今这一舞蹈仍在即位大典上表演。",
  "japanese-early:flood": "约1100年前后以院政统治日本四十多年的白河院，据说曾举出三件他唯一无法控制的事：贺茂川的水、双六的骰子和比叡山的僧兵（山法师）。每隔几年，贺茂川就会淹没京都，冲走两岸的桥梁和房屋。朝廷专门设立了一个官职防鸭河使来维护堤防，东部各区的居民在雨季里都时刻留意着天色。",
  "japanese-early:wind": "934年十二月，诗人纪贯之卸任土佐的官职，乘船返回京城，并以一位女子的口吻在《土佐日记》中记下了这段旅程。一切都由风来决定。日复一日，船停在港里，因为风向不对；风一停，他们便提心吊胆地划出去，提防着海盗。有一次在风暴中，船长让贯之把珍贵的镜子扔进海里献给神灵，波浪便平息了。在整个旅途中，他一直哀悼着死在土佐的小女儿。",
  "japanese-early:fire": "960年九月，京都的皇宫发生了自794年建都以来的第一次火灾。大火从收藏宝物的宣阳殿附近燃起，在夜里蔓延到各座殿宇。精通音乐的村上天皇失去了珍贵的乐器和书籍；朝臣们最担心的是神镜。据传说，神镜从火焰中飞了出来，挂在了紫宸殿前的一棵樱树上。皇宫重建了，但此后还将多次被焚毁。",
  "japanese-early:quake": "《日本三代实录》记载，869年五月二十六日，一场大地震袭击了北方的陆奥。人们呼喊着倒在地上，站不起来；房屋倒塌，城下町多贺城被毁。随后海水如雷鸣般涌起，淹没了方圆数里的平原，约一千人溺死。贞观海啸几乎被遗忘，直到科学家们在土层中发现了它留下的沙子，而2011年的海啸几乎沿着同一条路径袭来。",
  "japanese-early:winter": "《枕草子》回忆，约995年的一个雪天早晨，中宫定子的房间为了御寒关上了格子窗，女官们围坐在火盆旁。中宫转向清少纳言问道：少纳言，香炉峰的雪怎么样了？清少纳言立刻会意。她让人把格子窗推起，卷起帘子，就像白居易诗中写的那样，白雪覆盖的庭院映入眼帘。中宫笑了。清少纳言写道，冬天最好是清晨。",
  "japanese-early:plague": "869年，瘟疫再次在京都夺去人们的生命，人们竖起了六十六支高大的长戟，代表日本的每一个国，并把牛头天王的神舆抬到神泉苑，以驱逐致病的怨灵。祇园御灵会，即祇园祭，就这样开始了。每年七月，京都仍然在街上拉着高耸的山鉾巡行，乐师们在上面演奏由笛、钲和鼓组成的祇园囃子，那铿锵而悠扬的声音，是一种祈求驱除瘟疫的祷告。",
  "japanese-early:birth": "1008年，藤原道长的女儿中宫彰子在父亲家中生下了一位皇子。侍奉她的紫式部把一切都记录了下来。僧人们在每个房间里诵经，灵媒在神灵被驱入身体时尖叫，人们撒米驱魔。分娩之后，房间里的一切都是白色的：帷幔、衣服、屏风。每天傍晚，婴儿洗浴时，射手们拨响弓弦（鸣弦），学者们朗读中国的经典。道长高兴极了，婴儿尿湿了他的衣服，他也毫不在意。",
  "japanese-early:death": "1027年十二月，曾是平安朝廷中最有权势之人的藤原道长，躺在他在京都所建的法成寺阿弥陀堂中，奄奄一息。他面向西方，手中握着五色丝线，线的另一端系在九尊金色阿弥陀佛像的手上，好让佛陀把他引往净土。僧人们日夜围着他念佛。这个曾经写下世界属于自己、如同满月的人，在祈求被接引而去的祷告中死去。",
  // ── Koreans, Silla–Goryeo: stories of Silla and Goryeo ──
  "koreans-early:showcase": "《三国史记》（삼국사기）记载，伽倻（가야）的嘉实王（가실왕）于6世纪命人制作了伽倻琴（가야금），琴师于勒（우륵）把它带到了新罗（신라），真兴王（진흥왕）让青年们学习他的十二首曲子。新罗宫廷音乐由三弦三竹（삼현삼죽）组成：玄琴（거문고）、伽倻琴和乡琵琶（향비파），配以大、中、小三种笛子，即大笒（대금）、中笒（중금）和小笒（소금）。僧人和花郎（화랑）吟唱乡歌（향가）。高丽（고려）又加入了唐宋宴乐（당악），1116年，徽宗送来了宋朝的大晟雅乐（대성아악）以及编钟编磬。《青山别曲》（청산별곡）等高丽歌谣（고려가요）至今仍在传唱。",
  "koreans-early:hunt": "1351年至1374年在位的高丽（고려）恭愍王（공민왕）既是国王，也是画家。一幅长期被视为他作品的小型绢画《天山大猎图》（천산대렵도），画的是头戴皮帽的骑手们在苍茫的平原上飞驰，其中一人在马上回身向后拉弓，鹿群四散奔逃。其画风属于草原骑手，高丽在与元朝（원）密切往来的一个世纪里对他们十分熟悉。如今只有残片留存，但仍捕捉到了追逐的速度。",
  "koreans-early:battle": "660年，新罗（신라）军队在黄山伐（황산벌）遭遇百济（백제）将军阶伯（계백）及其五千人，四次被击退。随后，将军金品日（김품일）派出了他十六岁的儿子、花郎（화랑）官昌（관창）。官昌单骑冲阵被俘；阶伯被他的年少所感动，放他活着回去。少年从井里喝了水，说自己活着回来感到羞耻，又冲了上去。这一次，他的首级被系在马鞍上送了回来。新罗士兵悲愤落泪，一齐冲锋，赢得了胜利。",
  "koreans-early:siege": "1231年，撒礼塔（살리타이）率领的蒙古（몽골）军队攻入高丽（고려），包围了北方要塞龟州（구주）。守将朴犀（박서）坚守了数月。蒙古人造攻城塔、挖地道，抛掷石块和燃烧的油；守军把铁水灌进地道，推下巨石，用泥浆和水扑灭火焰。一位身经百战的蒙古老将说，他从未见过像这样坚守的城池。直到高丽朝廷亲自下令让朴犀停止抵抗，龟州才打开了城门。",
  "koreans-early:gather": "《三国史记》（삼국사기）记载，828年，新罗（신라）使者金大廉（김대렴）从唐朝（당）带回了茶籽，兴德王（흥덕왕）命人把它们种在智异山（지리산）上。此前新罗人已经饮茶，但从此茶树在这里生长起来。山寺的僧人们在春天采摘嫩叶，在佛前献茶；到了高丽（고려），饮茶成了宫廷礼仪和诗人的雅趣。据说双溪寺（쌍계사）周围的野生茶树就源自那最初的茶籽。",
  "koreans-early:build": "《三国遗事》（삼국유사）记载，751年，新罗（신라）大臣金大城（김대성）在庆州（경주）附近开始了两项伟大的工程：为今生的父母建佛国寺（불국사），为前世的父母在其上方的山上建石窟庵（석굴암）石窟。石匠们切割花岗岩石块，不用灰浆便拼合成一个穹顶石室，一尊巨大的白色佛像面朝东海端坐其中，四周环绕着雕刻的护法和弟子。金大城在工程完成前去世；新罗完成了它，第一缕朝阳至今仍会照到佛像的脸上。",
  "koreans-early:voyage": "约723年，一位名叫慧超（혜초）的年轻新罗（신라）僧人从中国乘船前往印度，朝拜佛陀的圣地。四年间，他走遍了印度诸国，然后翻越帕米尔高原，经过波斯和中亚，从陆路回到长安（장안）。他写了一部简短的旅行日记《往五天竺国传》（왕오천축국전）。这部书失传了一千年，直到1908年才在敦煌（돈황）石窟的写本中发现了一个残卷，其中有他思念新罗的短诗。",
  "koreans-early:festival": "《三国史记》（삼국사기）记载，儒理王（유리왕）在位时，新罗（신라）都城的妇女被分为两队，各由一位公主率领。从七月中旬起，她们每天早晨聚在一起纺麻织布，一直干到深夜。八月十五日，人们丈量布匹，输的一方要向赢的一方献上酒食。大家载歌载舞，输的一方中有一位女子唱了一首哀婉动人的歌：会苏，会苏（회소곡）。这个节日叫作嘉俳（가배），是中秋（추석）的起源。",
  "koreans-early:games": "1975年，考古学家在排干庆州（경주）新罗（신라）宫苑的雁鸭池（안압지）时，发现了一枚有十四个面的木骰子，名叫酒令具（주령구）。每一面都写着一种酒令游戏中的惩罚：一次喝三杯、独自唱一首歌、无乐起舞、吟诵一首诗、让大家弹你的鼻子、被挠痒时笑出来，或者保持不动、一言不发。它是为贵族们在月下池边的宴会而制作的。原件在干燥处理时意外烧毁，但一件复制品让这个游戏流传了下来。",
  "koreans-early:ritual": "每年冬天，高丽（고려）都要在都城开京（개경）举行八关会（팔관회），这是一个祭祀天神、山神、河神以及佛陀的盛大节日。灯火照亮了宫廷，在装饰华丽的舞台上，舞者和乐师表演古老的新罗（신라）舞蹈。各地官员带着贡品前来，来自宋朝（송）、日本、女真（여진）之地乃至阿拉伯的商人也受到朝廷的接见。对高丽来说，这是一场全国性的仪式：国王、众神和百姓一同欢宴。",
  "koreans-early:rain": "《三国遗事》（삼국유사）记载，682年，一座小山向新罗（신라）海岸漂来。山上长着一竿竹子，白天分成两根，夜里又合为一根。神文王（신문왕）前去观看，一条龙告诉他，如果用这竹子做一支笛子，天下就会太平。他照做了。笛声一响，敌兵退却，疾病消散；干旱时它带来雨水，洪涝时它让天空放晴；风停了，浪也平了。这支笛子被命名为万波息笛（만파식적），即平息万波之笛。",
  "koreans-early:drought": "想象：一个干旱的夏天，在高丽（고려）的一个村子里，稻秧在龟裂的水田中发黄。村长派人报告当地的地方官，地方官在黎明时分带着长老们登上山中的神祠，献上一头猪和酒，山下寺院的一位僧人则诵经祈雨。孩子们被派去往干涸溪边的一条草龙身上泼水，尽管父母忧心忡忡，他们还是笑个不停。许多个傍晚，一家家人望着云在山丘上空来来去去，直到那一夜，雨点终于敲响了茅草屋顶。",
  "koreans-early:flood": "想象：某年夏天，新罗（신라）都城庆州（경주）阴雨连绵，兄山江（형산강）和流经宫殿的溪流一同泛滥。洪水冲过瓦房林立的街巷，人们爬上寺院庭院的围墙。水退之后，农民们发现田地被泥沙覆盖。国王打开了粮仓，僧人和村民们并肩劳作，重修河堤。新罗的史书经常记载这样的洪水，每次一两行，附上冲毁房屋的数目。",
  "koreans-early:wind": "1281年，高丽（고려）的木匠和水手奉元朝（원）之命，为第二次征讨日本建造了数百艘船，高丽将军金方庆（김방경）随东路军从合浦（합포）出航。八月，在日本海岸外，一场台风袭来。仓促建造的船只纷纷解体，成百艘地沉没，数以千计的高丽士兵和水手溺死。金方庆带着幸存者回到了故国。在高丽的港口，桨手们的遗孀们永远不会忘记那场被日本人称为神风的风暴。",
  "koreans-early:fire": "1232年，蒙古（몽골）劫掠者焚烧了大邱（대구）附近的符仁寺（부인사），连同两个世纪前雕刻的第一部高丽（고려）大藏经经版也被烧毁了。避难于江华岛（강화도）的高丽朝廷决定重新雕刻全部经版，作为祈求护佑的祷告。从1236年到1251年，僧人和工匠们将桦木和樱木浸泡、蒸煮、晾干，刻出了八万多块经版，据说每刻一个字都要行一次礼。这部《高丽大藏经》（팔만대장경）至今仍保存在海印寺（해인사）。",
  "koreans-early:thunder": "新罗（신라）都城庆州（경주）的皇龙寺（황룡사）木塔，由百济的建筑大师阿非知（아비지）于645年建成，高九层，约八十米，是朝鲜半岛最高的建筑。由于它高高耸立在平原之上，史书记载几个世纪里它一次又一次地遭到雷击，每一次新罗以及后来的高丽（고려）都会把它修复。庆州人望着风暴从塔顶滚过，觉得这九层塔在守护着这片土地。它屹立了将近六百年。",
  "koreans-early:winter": "约1241年，高丽（고려）诗人李奎报（이규보）写了六首歌咏园中蔬菜的诗。写到萝卜时，他说用盐水和酱腌过之后，整个漫长的冬天都很好吃。这是关于后来的泡菜（김치）最古老的记录之一。在他那个时代还没有辣椒；高丽人家把萝卜、黄瓜和青菜用盐腌在坛子里，埋进寒冷的土中，到了万物不生的雪天再挖出来。写了数千首诗的李奎报，关于萝卜要说的话和关于月亮的一样多。",
  "koreans-early:plague": "《三国遗事》（삼국유사）讲述了处容（처용）的故事，他是东海龙王之子，于9世纪70年代来侍奉新罗（신라）宪康王（헌강왕）。一天夜里他回到家，看见床上有两双腿：疫神化作人形，与他的妻子同寝。处容没有发怒。他唱着歌、跳着舞，走了出去。疫神深受感动，跪下发誓，凡是挂着处容画像的人家，它永远不会进入。朝鲜人把他的面像挂在门上，处容舞（처용무）至今仍在表演。",
  "koreans-early:birth": "《三国遗事》（삼국유사）讲述了新罗（신라）如何在公元前57年建国。庆州（경주）六个村落的首领聚集在山丘上祈求一位君王。山下一口名叫萝井（나정）的井边，电光闪烁，一匹白马跪在那里。他们下山时，白马长嘶一声飞上天去，留下一枚巨大的红色卵。从卵中孵出了一个光彩照人的男孩。他们在东泉溪为他沐浴时，鸟兽起舞，日月更加明亮。他们给他取名朴赫居世（박혁거세），意为光明照耀世界的人。",
  "koreans-early:wedding": "《三国遗事》（삼국유사）记载，百济（백제）一个以挖山药为生的贫穷青年薯童（서동），听说了新罗（신라）善花公主（선화공주）的美貌。他来到庆州（경주），把山药分给孩子们，教他们唱一首小曲（서동요）：善花公主，私下嫁了人，夜里去抱薯童郎。孩子们在每条街上都唱，直到国王听到，把女儿屈辱地逐出了宫。薯童在路上遇见了她，她最终还是嫁给了他。据说他后来成了百济的武王（무왕）。",
  "koreans-early:death": "8世纪，以吹笛闻名的新罗（신라）僧人月明师（월명사）失去了妹妹。在她的祭礼上，他唱了一首乡歌（향가）《祭亡妹歌》（제망매가）：生死之路就在此处，令我心生畏惧；你连一句“我走了”都没说就去了。就像早秋的风吹落的树叶，从同一根枝头飘散，我们不知将去往何方。《三国遗事》（삼국유사）说，这时一阵突如其来的风把给亡者的纸钱吹向了西方，吹向他祈愿与她重逢的净土。",
});
